// GENERATED by scripts/build-data.mjs — edit the files in data/sections/, not this one.
window.SECTIONS={"akshar-gu":{"items":[{"letter":"અ","char":"agni","text":{"gu":"અગ્નિ પવિત્ર છે. દીવા અને યજ્ઞમાં અગ્નિની પૂજા થાય છે. તે અંધારું દૂર કરી પ્રકાશ આપે છે.","hi":"अग्नि पवित्र है। दीपक और यज्ञ में अग्नि की पूजा होती है। वह अंधेरा दूर कर प्रकाश देती है।","en":"Agni, the sacred fire, is honoured in the lamp and in yajna. It removes darkness and gives light."},"shot":{"subject":"a calm sacred fire with golden flames rising from a brass fire-pit","setting":"a simple yajna ground at dawn with flowers and a ghee pot"}},{"letter":"આ","char":"aarti","text":{"gu":"આરતીમાં દીવો ફેરવીને ભગવાનને યાદ કરીએ છીએ. ઘંટડી વાગે છે અને બધા સાથે ગાય છે.","hi":"आरती में दीपक घुमाकर हम भगवान को याद करते हैं। घंटी बजती है और सब साथ गाते हैं।","en":"In aarti we wave a lamp and remember God. A bell rings and everyone sings together."},"shot":{"subject":"a hand waving a lit aarti plate with a diya, flowers and incense","setting":"a cosy home temple corner in the evening"}},{"letter":"ઇ","char":"ikshvaku","text":{"gu":"રાજા ઇક્ષ્વાકુ સૂર્યવંશના પહેલા રાજા હતા. શ્રીરામ આ જ વંશમાં જન્મ્યા હતા.","hi":"राजा इक्ष्वाकु सूर्यवंश के पहले राजा थे। श्रीराम इसी वंश में जन्मे थे।","en":"King Ikshvaku was the first king of the Surya dynasty. Shri Ram was born in this same family."},"shot":{"subject":"a kind ancient king in a golden crown with a sun symbol on his chest","setting":"a royal garden with a glowing sun rising behind a palace"}},{"letter":"ઈ","char":"ishwar","text":{"gu":"ઈશ્વર એટલે ભગવાન. તે બધે છે અને બધાની રક્ષા કરે છે. આપણે રોજ તેમનો આભાર માનીએ છીએ.","hi":"ईश्वर यानी भगवान। वे हर जगह हैं और सबकी रक्षा करते हैं। हम रोज़ उनका आभार मानते हैं।","en":"Ishwar means God. God is everywhere and protects everyone. We thank God every day."},"shot":{"subject":"a child with folded hands looking up at a soft golden light with a glowing Om above","setting":"a sunrise hill with clouds and a small temple"}},{"letter":"ઉ","char":"upanishad","text":{"gu":"ઉપનિષદ ઋષિઓએ આપેલા જ્ઞાનના ગ્રંથો છે. ગુરુ પાસે બેસીને શીખવાથી જ્ઞાન મળે છે.","hi":"उपनिषद ऋषियों द्वारा दिए गए ज्ञान के ग्रंथ हैं। गुरु के पास बैठकर सीखने से ज्ञान मिलता है।","en":"The Upanishads are books of wisdom given by sages. We gain knowledge by sitting near a teacher and learning."},"shot":{"subject":"a sage teaching two children under a banyan tree with palm-leaf books","setting":"a forest ashram with a quiet stream"}},{"letter":"ઊ","char":"urmila","text":{"gu":"ઊર્મિલા લક્ષ્મણજીનાં પત્ની હતાં. તેમણે ધીરજથી પતિની રાહ જોઈ અને ત્યાગ કર્યો.","hi":"ऊर्मिला लक्ष्मण जी की पत्नी थीं। उन्होंने धैर्य से पति की प्रतीक्षा की और त्याग किया।","en":"Urmila was Laxman's wife. She waited patiently for her husband and made a great sacrifice."},"shot":{"subject":"a gentle queen in a green saree sitting by a window with a lit lamp","setting":"a palace room in Ayodhya at night with soft lamp light"}},{"letter":"ઋ","char":"rishi","text":{"gu":"ઋષિ એટલે જ્ઞાની સંત. તેઓ વનમાં રહે છે, ધ્યાન કરે છે અને બધાને સારું શીખવે છે.","hi":"ऋषि यानी ज्ञानी संत। वे वन में रहते हैं, ध्यान करते हैं और सबको अच्छी बातें सिखाते हैं।","en":"A rishi is a wise sage. Rishis live in the forest, meditate and teach everyone good things."},"shot":{"subject":"an elderly sage with white beard sitting in meditation with a glow around him","setting":"a green forest hermitage with deer nearby"}},{"letter":"એ","char":"ekadashi","text":{"gu":"એકાદશી પંદર દિવસે આવે છે. લોકો ઉપવાસ કરીને ભગવાન વિષ્ણુનું ભજન કરે છે.","hi":"एकादशी पंद्रह दिन में आती है। लोग व्रत रखकर भगवान विष्णु का भजन करते हैं।","en":"Ekadashi comes every fortnight. People fast lightly and sing bhajans for Lord Vishnu."},"shot":{"subject":"a small Vishnu idol with a tulsi leaf, a lamp and a plate of fruit","setting":"a clean puja room with morning light"}},{"letter":"ઐ","char":"airavat","text":{"gu":"ઐરાવત ઇન્દ્રદેવનો સફેદ હાથી છે. તે ચાર દાંતવાળો અને ખૂબ શક્તિશાળી છે.","hi":"ऐरावत इन्द्र देव का सफ़ेद हाथी है। वह चार दाँतों वाला और बहुत शक्तिशाली है।","en":"Airavat is the white elephant of Lord Indra. He is very strong and has four tusks."},"shot":{"subject":"a gentle large white elephant with four tusks and golden decorations","setting":"soft white clouds in the heavens at sunrise"}},{"letter":"ઓ","char":"omkareshwar","text":{"gu":"ઓમકારેશ્વર નર્મદા કિનારે આવેલું શિવજીનું પવિત્ર સ્થાન છે. ટેકરી ‘ઓમ’ જેવી દેખાય છે.","hi":"ओंकारेश्वर नर्मदा किनारे शिव जी का पवित्र स्थान है। पहाड़ी ‘ॐ’ के आकार की दिखती है।","en":"Omkareshwar is a holy place of Lord Shiva on the Narmada. The hill looks like the shape of ‘Om’."},"shot":{"subject":"an island hill shaped like Om with a temple on top","setting":"the Narmada river at sunrise with boats"}},{"letter":"ઔ","char":"aushadhi","text":{"gu":"ઔષધિ એટલે દવા આપતા છોડ, જેમ કે તુલસી અને હળદર. ઋષિઓ તેમને જાણતા હતા.","hi":"औषधि यानी दवा देने वाले पौधे, जैसे तुलसी और हल्दी। ऋषि इन्हें जानते थे।","en":"Aushadhi means healing herbs like tulsi and turmeric. The sages knew them well."},"shot":{"subject":"a basket of healing herbs, turmeric roots and tulsi leaves","setting":"a sunny herb garden near a hut"}},{"letter":"અં","char":"anjani","text":{"gu":"અંજની માતા હનુમાનજીનાં માતા છે. તેમણે ખૂબ પ્રેમથી હનુમાનને ઉછેર્યા.","hi":"अंजनी माता हनुमान जी की माँ हैं। उन्होंने बहुत प्रेम से हनुमान जी को पाला।","en":"Mother Anjani is the mother of Hanuman. She raised him with great love."},"shot":{"subject":"a loving mother with a baby Hanuman in her arms","setting":"a mountain cave garden with flowers and soft sunlight"}},{"letter":"અઃ","char":"shanti_mantra","text":{"gu":"‘શાંતિઃ’ શબ્દના અંતે અઃ આવે છે. પૂજા પછી ત્રણ વાર ‘ઓમ શાંતિઃ શાંતિઃ શાંતિઃ’ બોલીને શાંતિની પ્રાર્થના કરીએ છીએ.","hi":"‘शान्तिः’ शब्द के अंत में अः आता है। पूजा के बाद तीन बार ‘ॐ शान्तिः शान्तिः शान्तिः’ बोलकर शांति की प्रार्थना करते हैं।","en":"The word ‘Shantih’ ends with the sound ‘ah’. After puja we say ‘Om Shantih Shantih Shantih’ three times, praying for peace."},"shot":{"subject":"a child with folded hands and eyes closed, a soft white dove and a faint Om","setting":"a quiet garden at sunrise"},"exempt":true,"why":"No Gujarati word begins with અઃ; it appears at the end of words, so શાંતિઃ shows where it is used."},{"letter":"ક","char":"kamal","text":{"gu":"કમળ કાદવમાં ઊગે છે પણ સ્વચ્છ રહે છે. તે સુંદરતા અને પવિત્રતાની નિશાની છે.","hi":"कमल कीचड़ में उगता है पर स्वच्छ रहता है। यह सुंदरता और पवित्रता की निशानी है।","en":"The lotus grows in mud but stays clean. It is a sign of beauty and purity."},"shot":{"subject":"a bright pink lotus flower with a green leaf and a water drop","setting":"a calm pond at sunrise"}},{"letter":"ખ","char":"khadau","text":{"gu":"ખડાઉ લાકડાના પગરખાં છે. ભરતજીએ રામની ખડાઉ સિંહાસન પર મૂકી રાજ્ય ચલાવ્યું.","hi":"खड़ाऊँ लकड़ी की पादुकाएँ हैं। भरत जी ने राम की खड़ाऊँ सिंहासन पर रखकर राज्य चलाया।","en":"Khadau are wooden sandals. Bharat placed Ram's sandals on the throne and ruled in his name."},"shot":{"subject":"a pair of wooden sandals on a velvet cushion with flower garlands","setting":"a royal throne in a palace hall"}},{"letter":"ગ","char":"gaay","text":{"gu":"ગાય આપણી માતા જેવી છે. તે દૂધ આપે છે અને આપણે તેની સેવા અને રક્ષા કરીએ છીએ.","hi":"गाय हमारी माता जैसी है। वह दूध देती है और हम उसकी सेवा और रक्षा करते हैं।","en":"The cow is like our mother. She gives milk and we serve and protect her."},"shot":{"subject":"a gentle cow with a garland and a calf","setting":"a village field at sunrise"}},{"letter":"ઘ","char":"ghant","text":{"gu":"મંદિરનો ઘંટ વાગે ત્યારે મન શાંત થાય છે. ઘંટનો અવાજ સારા વિચારો જગાડે છે.","hi":"मंदिर की घंटी बजती है तो मन शांत होता है। घंटे की आवाज़ अच्छे विचार जगाती है।","en":"When the temple bell rings, the mind becomes calm. Its sound awakens good thoughts."},"shot":{"subject":"a large brass temple bell with a hanging rope","setting":"the temple entrance at sunrise"}},{"letter":"ચ","char":"chakra","text":{"gu":"સુદર્શન ચક્ર ભગવાન વિષ્ણુ અને શ્રીકૃષ્ણનું શસ્ત્ર છે. તે અધર્મથી રક્ષણ આપે છે.","hi":"सुदर्शन चक्र भगवान विष्णु और श्रीकृष्ण का शस्त्र है। यह अधर्म से रक्षा करता है।","en":"The Sudarshan Chakra is the discus of Lord Vishnu and Shri Krishna. It protects against adharma."},"shot":{"subject":"a glowing golden spinning Sudarshan Chakra","setting":"a calm blue sky with soft clouds"}},{"letter":"છ","char":"shivaji","text":{"gu":"છત્રપતિ શિવાજી મહારાજ બહાદુર રાજા હતા. તેમણે ધર્મ, પ્રજા અને સ્વરાજ્યની રક્ષા કરી.","hi":"छत्रपति शिवाजी महाराज वीर राजा थे। उन्होंने धर्म, प्रजा और स्वराज्य की रक्षा की।","en":"Chhatrapati Shivaji Maharaj was a brave king. He protected dharma, his people and his own homeland."},"shot":{"subject":"a young brave king in a saffron turban with a sword at his side, kind face","setting":"a hilltop fort at sunrise with a saffron flag"}},{"letter":"જ","char":"japmala","text":{"gu":"જપમાળા વડે આપણે ભગવાનનું નામ ગણીને જપ કરીએ છીએ. તેમાં ૧૦૮ મણકા હોય છે.","hi":"जपमाला से हम भगवान का नाम गिनकर जप करते हैं। उसमें १०८ मनके होते हैं।","en":"With a japa mala we count while chanting God's name. It has 108 beads."},"shot":{"subject":"a rudraksh japa mala held in a hand","setting":"a quiet corner with a window and soft morning light"}},{"letter":"ઝ","char":"jhanjh","text":{"gu":"ઝાંઝ ભજનમાં વગાડવાનું વાદ્ય છે. બે ઝાંઝ અથડાય ત્યારે મીઠો ખણખણ અવાજ આવે છે.","hi":"झाँझ भजन में बजाया जाने वाला वाद्य है। दो झाँझ टकराते हैं तो मीठी खनखन की आवाज़ आती है।","en":"Jhanjh are small cymbals played in bhajans. When two clash they make a sweet ringing sound."},"shot":{"subject":"a pair of small brass cymbals held by tiny hands","setting":"a village bhajan circle in the evening"}},{"letter":"ટ","char":"tilak","text":{"gu":"ટીલું કપાળ પર લગાવાય છે. તે આપણને ભગવાનની યાદ અપાવે છે અને શુભ ગણાય છે.","hi":"तिलक माथे पर लगाया जाता है। यह हमें भगवान की याद दिलाता है और शुभ माना जाता है।","en":"A tilak is applied on the forehead. It reminds us of God and is considered auspicious."},"shot":{"subject":"a child's forehead with a red tilak applied by an elder's finger","setting":"a bright home with a puja plate"}},{"letter":"ઠ","char":"thakorji","text":{"gu":"ઠાકોરજી એટલે શ્રીકૃષ્ણનું બાળસ્વરૂપ. ઘરમાં તેમને સવારે જગાડી, સ્નાન કરાવી, ભોગ ધરાવાય છે.","hi":"ठाकुर जी यानी श्रीकृष्ण का बाल स्वरूप। घर में उन्हें सुबह जगाकर, स्नान कराकर भोग लगाया जाता है।","en":"Thakorji is the child form of Shri Krishna. At home he is woken in the morning, bathed and offered food."},"shot":{"subject":"a small decorated Krishna idol in a little swing with a peacock feather","setting":"a home temple with flowers and lamps"}},{"letter":"ડ","char":"damru","text":{"gu":"ડમરુ શિવજીનું નાનું ઢોલ છે. તેના અવાજથી જ બધા સૂરો અને ભાષા બની એમ કહેવાય છે.","hi":"डमरू शिव जी का छोटा ढोल है। कहा जाता है कि इसकी ध्वनि से सभी सुर और भाषाएँ बनीं।","en":"The damru is Shiva's small drum. It is said that all music and language came from its sound."},"shot":{"subject":"a small two-sided damru drum with a hanging cord","setting":"a snowy Kailash backdrop at sunrise"}},{"letter":"ઢ","char":"dhol","text":{"gu":"ઢોલ તહેવારમાં વાગે છે. ઢોલનો તાલ સાંભળીને બાળકો નાચવા લાગે છે.","hi":"ढोल त्योहार में बजता है। ढोल की ताल सुनकर बच्चे नाचने लगते हैं।","en":"The dhol plays during festivals. Children start dancing when they hear its beat."},"shot":{"subject":"a colourful dhol drum with drumsticks","setting":"a village festival ground with flags"}},{"letter":"ણ","char":"sadguna","text":{"gu":"‘સદ્ગુણ’ શબ્દના અંતે ‘ણ’ આવે છે. સત્ય, દયા અને ધીરજ જેવા સદ્ગુણોથી જીવન સુંદર બને છે.","hi":"‘सद्गुण’ शब्द के अंत में ‘ण’ आता है। सत्य, दया और धैर्य जैसे सद्गुणों से जीवन सुंदर बनता है।","en":"The word ‘sadguna’ ends with ‘ṇa’. Good virtues like truth, kindness and patience make life beautiful."},"shot":{"subject":"three glowing flowers in a child's cupped hands, each a different colour","setting":"a bright garden path"},"exempt":true,"why":"Gujarati ણ rarely begins a word; it appears in the middle or end, so the word સદ્ગુણ shows it at the end."},{"letter":"ત","char":"tulsi","text":{"gu":"તુલસી પવિત્ર છોડ છે. દરેક ઘરના આંગણામાં તેની પૂજા થાય છે અને તે દવા પણ છે.","hi":"तुलसी पवित्र पौधा है। हर घर के आँगन में उसकी पूजा होती है और यह औषधि भी है।","en":"Tulsi is a sacred plant. It is worshipped in the courtyard of every home and also serves as medicine."},"shot":{"subject":"a healthy tulsi plant in a decorated tulsi pot (tulsi vrindavan) with a diya","setting":"a home courtyard at sunrise"}},{"letter":"થ","char":"thali","text":{"gu":"પૂજાની થાળીમાં દીવો, ફૂલ, કંકુ અને પ્રસાદ હોય છે. આપણે તે પ્રેમથી સજાવીએ છીએ.","hi":"पूजा की थाली में दीया, फूल, कुमकुम और प्रसाद होता है। हम उसे प्रेम से सजाते हैं।","en":"A puja thali holds a diya, flowers, kumkum and prasad. We decorate it with love."},"shot":{"subject":"a decorated brass puja thali with diya, flowers and kumkum","setting":"a wooden table near a home temple"}},{"letter":"દ","char":"divo","text":{"gu":"દીવો અંધારું દૂર કરે છે. દિવાળીએ ઘરમાં ઘણા દીવા પ્રગટાવાય છે અને ઘર ઝગમગે છે.","hi":"दीपक अंधेरा दूर करता है। दीवाली पर घर में कई दीप जलाए जाते हैं और घर जगमगाता है।","en":"A diya removes darkness. On Diwali many diyas are lit and the home sparkles."},"shot":{"subject":"a lit clay diya with a warm flame","setting":"a doorstep with rangoli in the evening"}},{"letter":"ધ","char":"dhaja","text":{"gu":"ધજા ધર્મની નિશાની છે. મંદિર પર ફરકતી ધજા દૂરથી પણ ભગવાનની યાદ અપાવે છે.","hi":"ध्वजा धर्म की निशानी है। मंदिर पर लहराती ध्वजा दूर से भी भगवान की याद दिलाती है।","en":"The dhaja is a sign of dharma. A flag fluttering on a temple reminds us of God even from afar."},"shot":{"subject":"a saffron flag on a tall temple spire","setting":"a blue sky with soft clouds"}},{"letter":"ન","char":"nandi","text":{"gu":"નંદી શિવજીનો પ્રિય નંદી બળદ છે. તે શાંત અને વફાદાર છે અને દરેક શિવમંદિરની બહાર બેઠેલો હોય છે.","hi":"नंदी शिव जी का प्रिय बैल है। वह शांत और वफ़ादार है और हर शिव मंदिर के बाहर बैठा रहता है।","en":"Nandi is Shiva's beloved bull. He is calm and loyal and sits outside every Shiva temple."},"shot":{"subject":"a gentle white bull resting with a garland","setting":"a stone courtyard of a Shiva temple"}},{"letter":"પ","char":"pipal","text":{"gu":"પીપળો મોટું અને પવિત્ર ઝાડ છે. તેનાં પાંદડાં ધ્રૂજે છે અને તે ખૂબ ઓક્સિજન આપે છે.","hi":"पीपल बड़ा और पवित्र वृक्ष है। उसके पत्ते हिलते रहते हैं और वह बहुत ऑक्सीजन देता है।","en":"The peepal is a large sacred tree. Its leaves flutter and it gives a lot of oxygen."},"shot":{"subject":"a big peepal tree with heart-shaped leaves","setting":"a village square under the tree"}},{"letter":"ફ","char":"ful","text":{"gu":"ફૂલ ભગવાનને પ્રેમથી ચડાવાય છે. ગલગોટા, ગુલાબ અને કમળ સુગંધ અને રંગ ફેલાવે છે.","hi":"फूल भगवान को प्रेम से चढ़ाए जाते हैं। गेंदा, गुलाब और कमल सुगंध और रंग फैलाते हैं।","en":"Flowers are offered to God with love. Marigold, rose and lotus spread fragrance and colour."},"shot":{"subject":"a basket of marigold, rose and lotus flowers","setting":"a sunny garden"}},{"letter":"બ","char":"bilipatra","text":{"gu":"બીલીપત્ર ત્રણ પાંદડાંવાળું હોય છે. શિવજીને તે ખૂબ પ્રિય છે અને શ્રદ્ધાથી ચડાવાય છે.","hi":"बेलपत्र तीन पत्तों वाला होता है। शिव जी को वह बहुत प्रिय है और श्रद्धा से चढ़ाया जाता है।","en":"Bilva leaves come in groups of three. They are dear to Lord Shiva and offered with faith."},"shot":{"subject":"a three-leaved bilva leaf on a Shivling with a little water drop","setting":"a quiet Shiva temple morning"}},{"letter":"ભ","char":"bhajan","text":{"gu":"ભજન ભગવાનનાં ગીત છે. સાથે બેસીને ભજન ગાવાથી મન ખુશ અને શાંત થાય છે.","hi":"भजन भगवान के गीत हैं। साथ बैठकर भजन गाने से मन प्रसन्न और शांत होता है।","en":"Bhajans are songs for God. Singing them together makes the mind happy and calm."},"shot":{"subject":"a group of children and elders sitting together singing with a harmonium","setting":"a village courtyard at dusk"}},{"letter":"મ","char":"mor","text":{"gu":"મોર આપણું રાષ્ટ્રીય પક્ષી છે. શ્રીકૃષ્ણ તેનું મોરપીંછ મુગટમાં લગાવતા.","hi":"मोर हमारा राष्ट्रीय पक्षी है। श्रीकृष्ण उसका मोरपंख मुकुट में लगाते थे।","en":"The peacock is our national bird. Shri Krishna wore its feather in his crown."},"shot":{"subject":"a peacock with its feathers fanned out","setting":"a green meadow after rain"}},{"letter":"ય","char":"yajna","text":{"gu":"યજ્ઞમાં અગ્નિમાં આહુતિ અપાય છે અને મંત્ર બોલાય છે. તે વાતાવરણ શુદ્ધ કરે છે અને શાંતિ આપે છે.","hi":"यज्ञ में अग्नि में आहुति दी जाती है और मंत्र बोले जाते हैं। यह वातावरण शुद्ध करता है और शांति देता है।","en":"In a yajna offerings are made into the fire with mantras. It purifies the surroundings and brings peace."},"shot":{"subject":"a small yajna fire with a copper pot, ghee and mango wood","setting":"a green open ground with priests seated"}},{"letter":"ર","char":"rathyatra","text":{"gu":"રથયાત્રામાં ભગવાન જગન્નાથ રથમાં બેસી નગરમાં ફરે છે. લોકો દોરડાથી રથ ખેંચે છે.","hi":"रथयात्रा में भगवान जगन्नाथ रथ में बैठकर नगर में घूमते हैं। लोग रस्सी से रथ खींचते हैं।","en":"In Rath Yatra Lord Jagannath rides a chariot through the city. People pull the chariot with ropes."},"shot":{"subject":"a large colourful Jagannath chariot with flags","setting":"a festive street with crowds"}},{"letter":"લ","char":"ladu","text":{"gu":"લાડુ મીઠો પ્રસાદ છે. ગણપતિ બાપ્પાને મોદક અને લાડુ ખૂબ ગમે છે.","hi":"लड्डू मीठा प्रसाद है। गणपति बप्पा को मोदक और लड्डू बहुत पसंद हैं।","en":"Laddu is a sweet prasad. Lord Ganesh loves modak and laddu very much."},"shot":{"subject":"a plate of golden round laddoos","setting":"a festive kitchen table"}},{"letter":"વ","char":"vad","text":{"gu":"વડ વિશાળ અને ઘટાદાર ઝાડ છે. તેની વડવાઈઓ નીચે સુધી આવે છે અને તે ખૂબ છાંયો આપે છે.","hi":"बरगद विशाल और घना वृक्ष है। उसकी जटाएँ नीचे तक आती हैं और वह बहुत छाया देता है।","en":"The banyan is a huge and shady tree. Its hanging roots reach the ground and it gives lots of shade."},"shot":{"subject":"a giant banyan tree with hanging roots","setting":"a village with children playing underneath"}},{"letter":"શ","char":"shankh","text":{"gu":"શંખ ફૂંકવાથી પવિત્ર અવાજ આવે છે. પૂજાની શરૂઆતમાં શંખનાદ કરાય છે.","hi":"शंख फूँकने से पवित्र ध्वनि आती है। पूजा की शुरुआत में शंखनाद किया जाता है।","en":"Blowing a conch makes a holy sound. A conch is blown at the start of puja."},"shot":{"subject":"a white conch shell with a gold rim","setting":"a home temple at sunrise"}},{"letter":"ષ","char":"shadritu","text":{"gu":"ભારતમાં છ ઋતુઓ આવે છે: વસંત, ગ્રીષ્મ, વર્ષા, શરદ, હેમંત અને શિશિર. દરેક ઋતુ કુદરતની ભેટ છે.","hi":"भारत में छह ऋतुएँ आती हैं: वसंत, ग्रीष्म, वर्षा, शरद, हेमंत और शिशिर। हर ऋतु प्रकृति का उपहार है।","en":"India has six seasons: spring, summer, monsoon, autumn, early winter and winter. Each season is nature's gift."},"shot":{"subject":"six small scenes in a circle showing flowers, sun, rain, harvest, mist and snow","setting":"a colourful ring of six season panels"}},{"letter":"સ","char":"swastik","text":{"gu":"સ્વસ્તિક શુભ અને કલ્યાણની પ્રાચીન નિશાની છે. દરેક પૂજા અને ઘરના પ્રવેશ પર તે દોરાય છે.","hi":"स्वस्तिक शुभ और कल्याण का प्राचीन चिह्न है। हर पूजा और घर के प्रवेश पर इसे बनाया जाता है।","en":"The Swastik is an ancient sign of auspiciousness and well-being. It is drawn at every puja and at the entrance of homes."},"shot":{"subject":"a red-and-yellow swastik drawn with kumkum on a door with flowers","setting":"a home entrance with rangoli"}},{"letter":"હ","char":"havan","text":{"gu":"હવનમાં મંત્રો સાથે અગ્નિમાં સામગ્રી અર્પણ કરાય છે. તે શુભ કાર્યોની શરૂઆતમાં થાય છે.","hi":"हवन में मंत्रों के साथ अग्नि में सामग्री अर्पित की जाती है। यह शुभ कार्यों की शुरुआत में होता है।","en":"In havan offerings are placed in the fire with mantras. It is done at the start of auspicious events."},"shot":{"subject":"a havan kund with small flames and a priest's hand offering","setting":"a decorated hall with flowers"}},{"letter":"ળ","char":"kalash","text":{"gu":"કળશમાં પાણી, આંબાનાં પાન અને નાળિયેર મૂકીએ છીએ. પૂજામાં તે શુભ ગણાય છે.","hi":"कलश में जल, आम के पत्ते और नारियल रखा जाता है। पूजा में यह शुभ माना जाता है।","en":"A kalash holds water, mango leaves and a coconut. It is considered auspicious in puja."},"shot":{"subject":"a copper kalash with mango leaves and a coconut on top","setting":"a puja platform with flowers"},"exempt":true,"why":"Gujarati ળ never begins a word; it is found in the middle (like કળશ), so the word shows it in the middle."},{"letter":"ક્ષ","char":"kshirsagar","text":{"gu":"ક્ષીરસાગર દૂધનો સમુદ્ર છે. ભગવાન વિષ્ણુ શેષનાગ પર ત્યાં શાંતિથી આરામ કરે છે.","hi":"क्षीरसागर दूध का सागर है। भगवान विष्णु शेषनाग पर वहाँ शांति से विश्राम करते हैं।","en":"The Kshirsagar is the ocean of milk. Lord Vishnu rests peacefully there on Sheshnag."},"shot":{"subject":"a calm milky ocean with a gentle ripple and a golden lotus","setting":"a glowing dawn sky"}},{"letter":"જ્ઞ","char":"gyan","text":{"gu":"જ્ઞાન સૌથી મોટું ધન છે. જેટલું આપણે વહેંચીએ તેટલું વધે છે.","hi":"ज्ञान सबसे बड़ा धन है। जितना हम बाँटते हैं उतना बढ़ता है।","en":"Knowledge is the greatest wealth. The more we share it, the more it grows."},"shot":{"subject":"an open book with a glowing lamp on top","setting":"a quiet study corner with morning sun"}}]},"akshar-hi":{"items":[{"letter":"अ","char":"ayodhya","text":{"hi":"अयोध्या श्रीराम की जन्मभूमि है। सरयू नदी के किनारे बसा यह नगर सूर्यवंश की राजधानी था।","gu":"અયોધ્યા શ્રીરામની જન્મભૂમિ છે. સરયૂ નદીના કિનારે વસેલું આ નગર સૂર્યવંશની રાજધાની હતું.","en":"Ayodhya is the birthplace of Shri Ram. This city on the river Saryu was the capital of the Surya dynasty."},"shot":{"subject":"a grand golden city with temple spires and flags","setting":"the banks of the Saryu at sunrise"}},{"letter":"आ","char":"adi_shankaracharya","text":{"hi":"आदि शंकराचार्य महान संत थे। उन्होंने पूरे भारत में चार मठ बनाकर ज्ञान का प्रकाश फैलाया।","gu":"આદિ શંકરાચાર્ય મહાન સંત હતા. તેમણે આખા ભારતમાં ચાર મઠ સ્થાપી જ્ઞાનનો પ્રકાશ ફેલાવ્યો.","en":"Adi Shankaracharya was a great saint. He set up four mathas across India and spread the light of knowledge."},"shot":{"subject":"a serene young monk in saffron robes with a staff and rudraksh","setting":"a mountain path with a small temple"}},{"letter":"इ","char":"indraprastha","text":{"hi":"इन्द्रप्रस्थ पांडवों की सुंदर राजधानी थी। वह यमुना के किनारे बसी बहुत भव्य नगरी थी।","gu":"ઇન્દ્રપ્રસ્થ પાંડવોની સુંદર રાજધાની હતી. તે યમુનાના કિનારે વસેલી ખૂબ ભવ્ય નગરી હતી.","en":"Indraprastha was the beautiful capital of the Pandavas. It was a very grand city on the banks of the Yamuna."},"shot":{"subject":"a shining palace city with arches and gardens","setting":"a river valley at sunrise"}},{"letter":"ई","char":"ishavasya","text":{"hi":"ईशावास्य उपनिषद सिखाता है कि सब कुछ ईश्वर का है। इसलिए हमें लालच नहीं करना चाहिए।","gu":"ઈશાવાસ્ય ઉપનિષદ શીખવે છે કે બધું ઈશ્વરનું છે. એટલે આપણે લોભ ન કરવો જોઈએ.","en":"The Isha Upanishad teaches that everything belongs to God. So we should not be greedy."},"shot":{"subject":"a sage holding a palm-leaf manuscript beside a glowing diya","setting":"a forest ashram"}},{"letter":"उ","char":"ujjain","text":{"hi":"उज्जैन शिव जी के महाकाल मंदिर का नगर है। यहाँ क्षिप्रा किनारे कुंभ का मेला लगता है।","gu":"ઉજ્જૈન શિવજીના મહાકાલ મંદિરનું નગર છે. અહીં ક્ષિપ્રા કિનારે કુંભ મેળો ભરાય છે.","en":"Ujjain is the city of Shiva's Mahakal temple. A Kumbh fair is held here on the Kshipra's bank."},"shot":{"subject":"a grand Mahakal-style temple with a flag","setting":"the river bank at dusk with lamps"}},{"letter":"ऊ","char":"usha","text":{"hi":"ऊषा भोर की देवी है। जब वह आती है तो अंधेरा हटता है और नया दिन शुरू होता है।","gu":"ઊષા સવારની દેવી છે. તે આવે ત્યારે અંધારું જાય છે અને નવો દિવસ શરૂ થાય છે.","en":"Usha is the goddess of dawn. When she comes the darkness leaves and a new day begins."},"shot":{"subject":"a gentle glowing lady of dawn in pink and gold sky robes","setting":"a golden sunrise over hills"}},{"letter":"ऋ","char":"rigveda","text":{"hi":"ऋग्वेद सबसे प्राचीन वेद है। इसमें सूर्य, अग्नि और प्रकृति की सुंदर प्रार्थनाएँ हैं।","gu":"ઋગ્વેદ સૌથી પ્રાચીન વેદ છે. તેમાં સૂર્ય, અગ્નિ અને પ્રકૃતિની સુંદર પ્રાર્થનાઓ છે.","en":"The Rigveda is the oldest Veda. It holds beautiful prayers to the Sun, Fire and nature."},"shot":{"subject":"an old palm-leaf manuscript on a wooden stand beside a lamp","setting":"a quiet hermitage by a stream"}},{"letter":"ए","char":"eknath","text":{"hi":"संत एकनाथ महाराष्ट्र के संत थे। वे सबके साथ प्रेम करते और सेवा में विश्वास रखते थे।","gu":"સંત એકનાથ મહારાષ્ટ્રના સંત હતા. તેઓ બધા સાથે પ્રેમ કરતા અને સેવામાં માનતા.","en":"Sant Eknath was a saint of Maharashtra. He loved everyone and believed in service."},"shot":{"subject":"a gentle saint in a white dhoti with a tilak and a tambura","setting":"a village by a river with a small temple"}},{"letter":"ऐ","char":"aishwarya","text":{"hi":"ऐश्वर्य यानी सुख-समृद्धि। लक्ष्मी जी की पूजा से हम प्रसन्नता और मेहनत से धन पाने की सीख लेते हैं।","gu":"ઐશ્વર્ય એટલે સુખ-સમૃદ્ધિ. લક્ષ્મીજીની પૂજાથી આપણે મહેનત અને આનંદથી સંપત્તિ મેળવવાની શીખ લઈએ છીએ.","en":"Aishwarya means prosperity. Worshipping Lakshmi reminds us to earn wealth with hard work and happiness."},"shot":{"subject":"a golden pot overflowing with coins and flowers","setting":"a decorated Diwali doorstep"}},{"letter":"ओ","char":"jagannath_puri","text":{"hi":"ओडिशा के जगन्नाथ पुरी में भगवान जगन्नाथ की रथयात्रा निकलती है। यह बहुत सुंदर और बड़ा उत्सव है।","gu":"ઓડિશાના જગન્નાથ પુરીમાં ભગવાન જગન્નાથની રથયાત્રા નીકળે છે. તે ખૂબ સુંદર મોટો ઉત્સવ છે.","en":"In Jagannath Puri, Odisha, the Rath Yatra of Lord Jagannath takes place. It is a grand and beautiful festival."},"shot":{"subject":"a colourful temple with a flag and a huge chariot","setting":"the sea shore at sunrise"}},{"letter":"औ","char":"audarya","text":{"hi":"औदार्य यानी उदारता। जो खुले मन से दूसरों को देता है, वह सबका प्रिय बन जाता है।","gu":"ઔદાર્ય એટલે ઉદારતા. જે ખુલ્લા મનથી બીજાને આપે છે તે બધાનો પ્રિય બને છે.","en":"Audarya means generosity. One who gives with an open heart becomes loved by everyone."},"shot":{"subject":"a child giving a share of fruit to another child with a bright smile","setting":"a village lane at morning"}},{"letter":"अं","char":"angad","text":{"hi":"अंगद बाली के पुत्र थे। वे राम के दूत बनकर रावण की सभा में गए और दृढ़ता से खड़े रहे।","gu":"અંગદ વાલીના પુત્ર હતા. તેઓ રામના દૂત બનીને રાવણની સભામાં ગયા અને દૃઢતાથી ઊભા રહ્યા.","en":"Angad was the son of Vali. He went as Ram's messenger to Ravan's court and stood firm."},"shot":{"subject":"a strong young vanara with a golden armband standing tall","setting":"a palace court with tall pillars"}},{"letter":"अः","char":"namah","text":{"hi":"‘नमः’ शब्द के अंत में अः आता है। ‘ॐ नमः शिवाय’ में हम शिव जी को प्रणाम करते हैं।","gu":"‘નમઃ’ શબ્દના અંતે અઃ આવે છે. ‘ઓમ નમઃ શિવાય’માં આપણે શિવજીને પ્રણામ કરીએ છીએ.","en":"The word ‘Namah’ ends with the sound ‘ah’. In ‘Om Namah Shivaya’ we bow to Lord Shiva."},"shot":{"subject":"a child with folded hands in namaste before a Shiva idol","setting":"a quiet temple corner"},"exempt":true,"why":"No Hindi word begins with अः; it appears at the end of words like नमः."},{"letter":"क","char":"kailash","text":{"hi":"कैलाश पर्वत शिव जी का निवास माना जाता है। वह बर्फ से ढका और बहुत शांत है।","gu":"કૈલાસ પર્વત શિવજીનું નિવાસ ગણાય છે. તે બરફથી ઢંકાયેલો અને ખૂબ શાંત છે.","en":"Mount Kailash is believed to be Shiva's home. It is covered in snow and very peaceful."},"shot":{"subject":"a majestic snow-covered peak glowing in soft morning light","setting":"clear blue sky with soft clouds"}},{"letter":"ख","char":"kheer","text":{"hi":"खीर दूध, चावल और चीनी से बनती है। यह प्रसाद में और त्योहारों में बनाई जाती है।","gu":"ખીર દૂધ, ચોખા અને ખાંડથી બને છે. તે પ્રસાદમાં અને તહેવારોમાં બનાવાય છે.","en":"Kheer is made of milk, rice and sugar. It is prepared as prasad and on festivals."},"shot":{"subject":"a bowl of creamy kheer with nuts","setting":"a festive kitchen"}},{"letter":"ग","char":"ganga","text":{"hi":"गंगा पवित्र नदी है। वह हिमालय से निकलकर लाखों लोगों को जल और जीवन देती है।","gu":"ગંગા પવિત્ર નદી છે. તે હિમાલયથી નીકળી લાખો લોકોને પાણી અને જીવન આપે છે.","en":"The Ganga is a holy river. She flows from the Himalayas and gives water and life to millions."},"shot":{"subject":"a sparkling silver-blue river flowing from the mountains","setting":"a green valley with a ghat and diyas"}},{"letter":"घ","char":"ghatotkach","text":{"hi":"घटोत्कच भीम के पुत्र थे। वे बलशाली थे और पांडवों की रक्षा में हमेशा आगे रहे।","gu":"ઘટોત્કચ ભીમના પુત્ર હતા. તેઓ બળવાન હતા અને પાંડવોની રક્ષામાં હંમેશાં આગળ રહ્યા.","en":"Ghatotkacha was the son of Bhima. He was strong and always stood ready to protect the Pandavas."},"shot":{"subject":"a tall, friendly, strong young warrior with curly hair and a kind face","setting":"a forest edge at dusk"}},{"letter":"च","char":"chitrakoot","text":{"hi":"चित्रकूट वह वन है जहाँ राम, सीता और लक्ष्मण ने समय बिताया। यहाँ मंदाकिनी नदी बहती है।","gu":"ચિત્રકૂટ તે વન છે જ્યાં રામ, સીતા અને લક્ષ્મણે સમય વિતાવ્યો. અહીં મંદાકિની નદી વહે છે.","en":"Chitrakoot is the forest where Ram, Sita and Laxman stayed. The Mandakini river flows here."},"shot":{"subject":"a calm forest hill with a river and a small hut","setting":"a golden morning light"}},{"letter":"छ","char":"chhath","text":{"hi":"छठ पूजा में उगते और डूबते सूर्य को अर्घ्य देते हैं। यह प्रकृति और सूर्य के प्रति आभार है।","gu":"છઠ પૂજામાં ઉગતા અને આથમતા સૂર્યને અર્ઘ્ય આપે છે. તે પ્રકૃતિ અને સૂર્ય પ્રત્યે આભાર છે.","en":"In Chhath Puja people offer water to the rising and setting Sun. It is gratitude for nature and the Sun."},"shot":{"subject":"a family standing in a river holding bamboo baskets with fruits towards the sun","setting":"a golden sunrise river scene"}},{"letter":"ज","char":"jatayu","text":{"hi":"जटायु बूढ़ा पर साहसी गिद्ध था। उसने सीता जी को बचाने के लिए रावण से लड़ाई की।","gu":"જટાયુ વૃદ્ધ પણ સાહસી ગીધ હતો. તેણે સીતાજીને બચાવવા રાવણ સામે લડત આપી.","en":"Jatayu was an old but brave vulture. He fought Ravan to rescue Sita."},"shot":{"subject":"a big noble vulture with outspread wings in the sky","setting":"a forest sky at sunrise"}},{"letter":"झ","char":"jhansi_rani","text":{"hi":"झाँसी की रानी लक्ष्मीबाई बहुत वीर थीं। उन्होंने अपनी मातृभूमि की रक्षा के लिए साहस दिखाया।","gu":"ઝાંસીની રાણી લક્ષ્મીબાઈ ખૂબ વીર હતી. તેમણે માતૃભૂમિની રક્ષા માટે હિંમત બતાવી.","en":"Rani Lakshmibai of Jhansi was very brave. She showed courage to protect her motherland."},"shot":{"subject":"a brave queen in a turban on a horse holding a sword and her child tied on her back","setting":"a fort on a hill at dawn"}},{"letter":"ट","char":"tapkeshwar","text":{"hi":"टपकेश्वर महादेव देहरादून की गुफा में है। यहाँ शिवलिंग पर ऊपर से जल की बूँदें टपकती हैं।","gu":"ટપકેશ્વર મહાદેવ દેહરાદૂનની ગુફામાં છે. અહીં શિવલિંગ પર ઉપરથી પાણીનાં ટીપાં ટપકે છે.","en":"Tapkeshwar Mahadev is in a cave in Dehradun. Drops of water fall on the Shivling from above."},"shot":{"subject":"a cave Shivling with water drops dripping from the roof","setting":"a quiet green cave entrance"}},{"letter":"ठ","char":"thandai","text":{"hi":"ठंडाई दूध, बादाम और इलायची से बनने वाला ठंडा पेय है। होली पर यह प्रेम से परोसा जाता है।","gu":"ઠંડાઈ દૂધ, બદામ અને એલચીથી બનતું ઠંડું પીણું છે. હોળી પર તે પ્રેમથી પીરસાય છે.","en":"Thandai is a cool drink of milk, almonds and cardamom. It is served with love on Holi."},"shot":{"subject":"a pitcher and cups of creamy thandai with petals","setting":"a festive courtyard with colours"}},{"letter":"ड","char":"dandiya","text":{"hi":"डांडिया गुजरात का नृत्य है। नवरात्रि में सब लोग रंगीन कपड़े पहनकर डंडियों से नाचते हैं।","gu":"ડાંડિયા ગુજરાતનું નૃત્ય છે. નવરાત્રિમાં બધા રંગીન કપડાં પહેરીને દાંડિયાથી નાચે છે.","en":"Dandiya is a dance of Gujarat. During Navratri everyone dances with sticks in bright clothes."},"shot":{"subject":"children dancing with colourful dandiya sticks","setting":"a Navratri festival ground with lights"}},{"letter":"ढ","char":"kabir","text":{"hi":"ढाई आखर प्रेम का पढ़े सो पंडित होय — संत कबीर ने कहा कि प्रेम के ढाई अक्षर समझ लें तो सब समझ आ जाता है।","gu":"ઢાઈ અક્ષર પ્રેમના — સંત કબીરે કહ્યું કે પ્રેમના અઢી અક્ષર સમજી લઈએ તો બધું સમજાઈ જાય.","en":"‘Dhai aakhar prem ka’ — Sant Kabir said that if we understand two-and-a-half letters of love, we understand everything."},"shot":{"subject":"a saint weaver in a simple white turban sitting at a loom with a smile","setting":"a village lane in the morning"}},{"letter":"ण","char":"pranam","text":{"hi":"‘प्रणाम’ शब्द के बीच में ‘ण’ आता है। बड़ों को प्रणाम करने से आशीर्वाद मिलता है।","gu":"‘પ્રણામ’ શબ્દના વચ્ચે ‘ણ’ આવે છે. વડીલોને પ્રણામ કરવાથી આશીર્વાદ મળે છે.","en":"The word ‘Pranam’ has ‘ṇa’ in the middle. Bowing to elders brings blessings."},"shot":{"subject":"a child touching the feet of a smiling grandfather","setting":"a courtyard at sunrise"},"exempt":true,"why":"Hindi ण never begins a word; it appears in the middle, as in प्रणाम."},{"letter":"त","char":"tulsidas","text":{"hi":"तुलसीदास जी ने रामचरितमानस लिखी। उनकी चौपाइयाँ आज भी घर-घर में गाई जाती हैं।","gu":"તુલસીદાસજીએ રામચરિતમાનસ લખી. તેમની ચોપાઈઓ આજે પણ ઘરોમાં ગવાય છે.","en":"Tulsidas wrote the Ramcharitmanas. His verses are still sung in homes today."},"shot":{"subject":"a saint with a quill and palm-leaf pages and a gentle smile","setting":"a riverside hut"}},{"letter":"थ","char":"thaneshwar","text":{"hi":"थानेश्वर कुरुक्षेत्र का प्राचीन तीर्थ है। यहाँ महादेव का मंदिर है और लोग श्रद्धा से आते हैं।","gu":"થાનેશ્વર કુરુક્ષેત્રનું પ્રાચીન તીર્થ છે. અહીં મહાદેવનું મંદિર છે અને લોકો શ્રદ્ધાથી આવે છે.","en":"Thaneshwar is an ancient pilgrimage place in Kurukshetra. It has a Mahadev temple where people come with faith."},"shot":{"subject":"a serene Shiva temple beside a pond","setting":"a clear morning"}},{"letter":"द","char":"dwarka","text":{"hi":"द्वारका श्रीकृष्ण की नगरी है। यह समुद्र के किनारे बसी थी और बहुत सुंदर थी।","gu":"દ્વારકા શ્રીકૃષ્ણની નગરી છે. તે સમુદ્ર કિનારે વસેલી અને ખૂબ સુંદર હતી.","en":"Dwarka is the city of Shri Krishna. It stood by the sea and was very beautiful."},"shot":{"subject":"a golden city beside the sea with a tall temple flag","setting":"a sunrise over the ocean"}},{"letter":"ध","char":"dhanvantari","text":{"hi":"धन्वंतरि आयुर्वेद के देवता हैं। वे अमृत कलश और औषधियाँ लेकर समुद्र मंथन से प्रकट हुए।","gu":"ધન્વંતરિ આયુર્વેદના દેવ છે. તેઓ અમૃત કળશ અને ઔષધિઓ સાથે સમુદ્રમંથનથી પ્રગટ થયા.","en":"Dhanvantari is the god of Ayurveda. He appeared from the churning of the ocean with the nectar pot and herbs."},"shot":{"subject":"a kind four-armed deity in white holding a kalash and herbs","setting":"a glowing ocean sky"}},{"letter":"न","char":"narmada","text":{"hi":"नर्मदा पवित्र नदी है। कहा जाता है कि उसके दर्शन मात्र से मन शांत हो जाता है।","gu":"નર્મદા પવિત્ર નદી છે. કહેવાય છે કે તેના દર્શનથી જ મન શાંત થાય છે.","en":"The Narmada is a holy river. It is said that just seeing her calms the mind."},"shot":{"subject":"a wide serene river with stone ghats","setting":"a green valley with soft light"}},{"letter":"प","char":"patanjali","text":{"hi":"पतंजलि ने योग के सूत्र लिखे। योग हमारे शरीर और मन को स्वस्थ और शांत रखता है।","gu":"પતંજલિએ યોગસૂત્રો લખ્યાં. યોગ આપણા શરીર અને મનને સ્વસ્થ અને શાંત રાખે છે.","en":"Patanjali wrote the Yoga Sutras. Yoga keeps our body and mind healthy and calm."},"shot":{"subject":"a sage in a yoga pose with a gentle glow","setting":"a green hermitage garden"}},{"letter":"फ","char":"phagun","text":{"hi":"फागुन में होली आती है। रंग उड़ते हैं और सब मिलकर प्रेम और खुशी मनाते हैं।","gu":"ફાગણમાં હોળી આવે છે. રંગ ઊડે છે અને બધા સાથે પ્રેમ અને ખુશી ઊજવે છે.","en":"Holi comes in the month of Phagun. Colours fly and everyone celebrates love and joy together."},"shot":{"subject":"children throwing coloured gulal powder into the air","setting":"a sunny village square"}},{"letter":"ब","char":"badrinath","text":{"hi":"बद्रीनाथ हिमालय में भगवान विष्णु का पवित्र धाम है। यह बर्फीले पहाड़ों के बीच बसा है।","gu":"બદ્રીનાથ હિમાલયમાં ભગવાન વિષ્ણુનું પવિત્ર ધામ છે. તે બરફીલા પર્વતો વચ્ચે વસેલું છે.","en":"Badrinath is a holy abode of Lord Vishnu in the Himalayas. It stands among snowy mountains."},"shot":{"subject":"a colourful temple with snowy peaks behind","setting":"a clear mountain morning"}},{"letter":"भ","char":"bharat","text":{"hi":"भरत जी राम के भाई थे। उन्होंने राम की खड़ाऊँ को सिंहासन पर रखकर प्रेम से सेवा की।","gu":"ભરતજી રામના ભાઈ હતા. તેમણે રામની ખડાઉ સિંહાસન પર મૂકીને પ્રેમથી સેવા કરી.","en":"Bharat was Ram's brother. He placed Ram's sandals on the throne and served with love."},"shot":{"subject":"a humble prince in simple clothes holding wooden sandals on his head","setting":"a forest path at sunrise"}},{"letter":"म","char":"mathura","text":{"hi":"मथुरा श्रीकृष्ण की जन्मभूमि है। यहाँ यमुना बहती है और जन्माष्टमी बड़े उत्साह से मनाई जाती है।","gu":"મથુરા શ્રીકૃષ્ણની જન્મભૂમિ છે. અહીં યમુના વહે છે અને જન્માષ્ટમી ઉત્સાહથી ઊજવાય છે.","en":"Mathura is the birthplace of Shri Krishna. The Yamuna flows here and Janmashtami is celebrated with joy."},"shot":{"subject":"a temple city with ghats on the Yamuna","setting":"a lamp-lit evening"}},{"letter":"य","char":"yamuna","text":{"hi":"यमुना नदी श्रीकृष्ण को बहुत प्रिय है। उसके किनारे उन्होंने गायें चराईं और बाँसुरी बजाई।","gu":"યમુના નદી શ્રીકૃષ્ણને ખૂબ પ્રિય છે. તેના કિનારે તેમણે ગાયો ચરાવી અને વાંસળી વગાડી.","en":"The Yamuna river is dear to Shri Krishna. On her banks he grazed cows and played his flute."},"shot":{"subject":"a calm blue-dark river with kadamba trees and a flute on the bank","setting":"a golden evening"}},{"letter":"र","char":"rameshwaram","text":{"hi":"रामेश्वरम में श्रीराम ने शिवलिंग की पूजा की थी। यह चार धामों में से एक है।","gu":"રામેશ્વરમમાં શ્રીરામે શિવલિંગની પૂજા કરી હતી. તે ચાર ધામમાંનું એક છે.","en":"At Rameshwaram Shri Ram worshipped the Shivling. It is one of the four dhams."},"shot":{"subject":"a long-pillared temple corridor and the sea","setting":"a blue seaside morning"}},{"letter":"ल","char":"lota","text":{"hi":"लोटा पीतल या ताँबे का छोटा बर्तन है। इससे सूर्य को जल और भगवान को अभिषेक करते हैं।","gu":"લોટો પિત્તળ કે તાંબાનું નાનું વાસણ છે. તેનાથી સૂર્યને જળ અને ભગવાનનો અભિષેક કરાય છે.","en":"A lota is a small brass or copper pot. We use it to offer water to the Sun and to bathe the deity."},"shot":{"subject":"a shiny brass lota with a little water spilling","setting":"a sunny courtyard"}},{"letter":"व","char":"valmiki","text":{"hi":"वाल्मीकि ऋषि ने रामायण लिखी। पहले वे डाकू थे, पर नारद जी के उपदेश से तपस्या कर महर्षि बने।","gu":"વાલ્મીકિ ઋષિએ રામાયણ લખી. પહેલાં તેઓ ડાકુ હતા, પણ નારદજીના ઉપદેશથી તપસ્યા કરી મહર્ષિ બન્યા.","en":"Sage Valmiki wrote the Ramayana. He was once a robber, but after Narad's teaching he did tapasya and became a great sage."},"shot":{"subject":"a white-bearded sage writing on a palm-leaf with a quill, an ant-hill behind him","setting":"a riverside hermitage"}},{"letter":"श","char":"sheshnag","text":{"hi":"शेषनाग भगवान विष्णु की शैय्या हैं। वे हजार फनों से धरती को सँभाले रखते हैं।","gu":"શેષનાગ ભગવાન વિષ્ણુની શૈયા છે. તેઓ હજાર ફેણથી ધરતીને સંભાળે છે.","en":"Sheshnag is Lord Vishnu's bed. With a thousand hoods he is said to hold up the earth."},"shot":{"subject":"a large friendly serpent with many hoods coiled like a bed","setting":"a glowing milky ocean"}},{"letter":"ष","char":"kartikeya","text":{"hi":"षडानन यानी कार्तिकेय जी के छह मुख हैं। वे शिव-पार्वती के पुत्र और देवताओं के सेनापति हैं।","gu":"ષડાનન એટલે કાર્તિકેયજી, જેમનાં છ મુખ છે. તેઓ શિવ-પાર્વતીના પુત્ર અને દેવોના સેનાપતિ છે.","en":"Shadanan, Kartikeya, has six faces. He is the son of Shiva and Parvati and the commander of the gods."},"shot":{"subject":"a young six-faced god standing beside a peacock with a spear","setting":"a mountain sunrise"}},{"letter":"स","char":"saryu","text":{"hi":"सरयू नदी अयोध्या के पास बहती है। राम और भरत इसके किनारे खेले थे।","gu":"સરયૂ નદી અયોધ્યા પાસે વહે છે. રામ અને ભરત તેના કિનારે રમ્યા હતા.","en":"The river Saryu flows by Ayodhya. Ram and Bharat played on its banks."},"shot":{"subject":"a calm river with stone steps and lamps","setting":"a sunrise with birds"}},{"letter":"ह","char":"haridwar","text":{"hi":"हरिद्वार में गंगा पहाड़ों से मैदान में उतरती है। यहाँ शाम को गंगा आरती होती है।","gu":"હરિદ્વારમાં ગંગા પહાડોથી મેદાનમાં ઊતરે છે. અહીં સાંજે ગંગા આરતી થાય છે.","en":"At Haridwar the Ganga comes down from the mountains to the plains. A Ganga aarti is performed here in the evening."},"shot":{"subject":"a ghat with floating diyas and bells","setting":"a river dusk"}},{"letter":"क्ष","char":"kshipra","text":{"hi":"क्षिप्रा नदी उज्जैन से बहती है। यहाँ हर बारह वर्ष में कुंभ स्नान का मेला लगता है।","gu":"ક્ષિપ્રા નદી ઉજ્જૈનમાંથી વહે છે. અહીં દર બાર વર્ષે કુંભ સ્નાનનો મેળો ભરાય છે.","en":"The river Kshipra flows through Ujjain. A Kumbh bathing fair is held here every twelve years."},"shot":{"subject":"a calm river with steps and pilgrims bathing at sunrise","setting":"a temple tower behind"}},{"letter":"त्र","char":"trishul","text":{"hi":"त्रिशूल शिव जी का शस्त्र है। इसके तीन फल सत्य, कर्म और ज्ञान के प्रतीक हैं।","gu":"ત્રિશૂલ શિવજીનું શસ્ત્ર છે. તેના ત્રણ ફળાં સત્ય, કર્મ અને જ્ઞાનના પ્રતીક છે.","en":"The trishul is Shiva's trident. Its three prongs stand for truth, action and knowledge."},"shot":{"subject":"a gleaming trident with a damru and a flower","setting":"a snowy Kailash backdrop"}},{"letter":"ज्ञ","char":"gyaneshwar","text":{"hi":"संत ज्ञानेश्वर ने कम उम्र में गीता पर ज्ञानेश्वरी लिखी। वे बहुत ज्ञानी और दयालु थे।","gu":"સંત જ્ઞાનેશ્વરે નાની ઉંમરે ગીતા પર જ્ઞાનેશ્વરી લખી. તેઓ ખૂબ જ્ઞાની અને દયાળુ હતા.","en":"Sant Dnyaneshwar wrote the Dnyaneshwari on the Gita at a young age. He was very wise and kind."},"shot":{"subject":"a young saint with a gentle face and a palm-leaf book","setting":"a village temple garden"}}]},"numbers":{"items":[{"id":"n1","n":1,"names":{"gu":"એક","hi":"एक","en":"One"},"stands":{"gu":"ઈશ્વર એક છે","hi":"ईश्वर एक हैं","en":"God is One"},"text":{"gu":"એક ઈશ્વર સૌનું ધ્યાન રાખે છે. એક સૂર્ય આખી દુનિયાને પ્રકાશ આપે છે, અને એક મનથી કરેલું કામ સફળ થાય છે.","hi":"एक ईश्वर सबका ध्यान रखते हैं। एक सूर्य पूरी दुनिया को प्रकाश देता है, और एक मन से किया काम सफल होता है।","en":"One God looks after everyone. One Sun lights the whole world, and work done with one focused mind succeeds."},"shot":{"subject":"a single glowing diya with a big number 1 shape formed by its flame","setting":"a calm dark background with a soft golden halo"}},{"id":"n2","n":2,"names":{"gu":"બે","hi":"दो","en":"Two"},"stands":{"gu":"જોડી: સીતા-રામ, રાધા-કૃષ્ણ","hi":"जोड़ी: सीता-राम, राधा-कृष्ण","en":"Pairs: Sita-Ram, Radha-Krishna"},"text":{"gu":"બે હાથ જોડીને નમસ્તે કરીએ છીએ. સીતા-રામ અને રાધા-કૃષ્ણ જેવી જોડીઓ પ્રેમ અને સાથનું પ્રતીક છે.","hi":"दो हाथ जोड़कर हम नमस्ते करते हैं। सीता-राम और राधा-कृष्ण जैसी जोड़ियाँ प्रेम और साथ का प्रतीक हैं।","en":"We greet with two folded hands. Pairs like Sita-Ram and Radha-Krishna stand for love and togetherness."},"shot":{"subject":"two small hands folded in namaste with two flower buds","setting":"a soft pink and cream background"}},{"id":"n3","n":3,"names":{"gu":"ત્રણ","hi":"तीन","en":"Three"},"stands":{"gu":"ત્રિમૂર્તિ: બ્રહ્મા, વિષ્ણુ, મહેશ","hi":"त्रिमूर्ति: ब्रह्मा, विष्णु, महेश","en":"Trimurti: Brahma, Vishnu, Mahesh"},"text":{"gu":"ભગવાનના ત્રણ રૂપો છે: બ્રહ્મા સર્જન કરે, વિષ્ણુ પાલન કરે અને મહેશ (શિવ) પરિવર્તન કરે છે.","hi":"भगवान के तीन रूप हैं: ब्रह्मा सृजन करते हैं, विष्णु पालन करते हैं और महेश (शिव) परिवर्तन करते हैं।","en":"God has three forms: Brahma creates, Vishnu preserves and Mahesh (Shiva) transforms."},"shot":{"subject":"three glowing lotuses of different colours in a row","setting":"a gentle blue-gold sky"}},{"id":"n4","n":4,"names":{"gu":"ચાર","hi":"चार","en":"Four"},"stands":{"gu":"ચાર વેદ","hi":"चार वेद","en":"The four Vedas"},"text":{"gu":"ઋગ્વેદ, યજુર્વેદ, સામવેદ અને અથર્વવેદ — આ ચાર વેદ જ્ઞાનનો ભંડાર છે.","hi":"ऋग्वेद, यजुर्वेद, सामवेद और अथर्ववेद — ये चार वेद ज्ञान का भंडार हैं।","en":"Rigveda, Yajurveda, Samaveda and Atharvaveda — the four Vedas are a treasure of knowledge."},"shot":{"subject":"four palm-leaf books tied with threads of four colours","setting":"a warm sandalwood background"}},{"id":"n5","n":5,"names":{"gu":"પાંચ","hi":"पाँच","en":"Five"},"stands":{"gu":"પાંચ પાંડવ, પંચ તત્વ","hi":"पाँच पांडव, पंच तत्व","en":"Five Pandavas, five elements"},"text":{"gu":"યુધિષ્ઠિર, ભીમ, અર્જુન, નકુલ અને સહદેવ — પાંચ પાંડવો. પૃથ્વી, જળ, અગ્નિ, વાયુ અને આકાશ — પાંચ તત્વો.","hi":"युधिष्ठिर, भीम, अर्जुन, नकुल और सहदेव — पाँच पांडव। पृथ्वी, जल, अग्नि, वायु और आकाश — पाँच तत्व।","en":"Yudhishthira, Bhima, Arjun, Nakul and Sahadev are the five Pandavas. Earth, water, fire, air and sky are the five elements."},"shot":{"subject":"five small symbols in a ring: leaf, water drop, flame, wind swirl, star","setting":"a calm earthy background"}},{"id":"n6","n":6,"names":{"gu":"છ","hi":"छह","en":"Six"},"stands":{"gu":"છ ઋતુઓ","hi":"छह ऋतुएँ","en":"Six seasons"},"text":{"gu":"વસંત, ગ્રીષ્મ, વર્ષા, શરદ, હેમંત અને શિશિર — છ ઋતુઓ આપણને કુદરતની ભેટ આપે છે.","hi":"वसंत, ग्रीष्म, वर्षा, शरद, हेमंत और शिशिर — छह ऋतुएँ हमें प्रकृति का उपहार देती हैं।","en":"Spring, summer, monsoon, autumn, early winter and winter — six seasons are nature's gift."},"shot":{"subject":"six small scene medallions of flowers, sun, rain, harvest, mist and snow","setting":"a bright colourful background"}},{"id":"n7","n":7,"names":{"gu":"સાત","hi":"सात","en":"Seven"},"stands":{"gu":"સપ્તર્ષિ, સાત સૂર, સપ્ત નદી","hi":"सप्तर्षि, सात सुर, सप्त नदी","en":"Seven sages, seven notes, seven rivers"},"text":{"gu":"સાત ઋષિઓ આકાશમાં સપ્તર્ષિ તારા-સમૂહ તરીકે ચમકે છે. સંગીતમાં સાત સૂર છે: સા રે ગ મ પ ધ ની.","hi":"सात ऋषि आकाश में सप्तर्षि तारा-समूह बनकर चमकते हैं। संगीत में सात सुर हैं: सा रे ग म प ध नी।","en":"Seven sages shine in the sky as the Saptarishi star group. Music has seven notes: Sa Re Ga Ma Pa Dha Ni."},"shot":{"subject":"seven glowing stars forming a gentle ladle shape","setting":"a deep blue night sky"}},{"id":"n8","n":8,"names":{"gu":"આઠ","hi":"आठ","en":"Eight"},"stands":{"gu":"અષ્ટલક્ષ્મી","hi":"अष्टलक्ष्मी","en":"Ashtalakshmi"},"text":{"gu":"લક્ષ્મીજીનાં આઠ રૂપ છે, જે ધન, ધાન્ય, હિંમત, જ્ઞાન, સંતાન, વિજય, કૃપા અને શક્તિ આપે છે.","hi":"लक्ष्मी जी के आठ रूप हैं, जो धन, धान्य, साहस, ज्ञान, संतान, विजय, कृपा और शक्ति देते हैं।","en":"Lakshmi has eight forms that give wealth, grain, courage, knowledge, children, victory, grace and strength."},"shot":{"subject":"an eight-petalled lotus glowing in gold","setting":"a soft golden background"}},{"id":"n9","n":9,"names":{"gu":"નવ","hi":"नौ","en":"Nine"},"stands":{"gu":"નવરાત્રિ, નવ દુર્ગા","hi":"नवरात्रि, नवदुर्गा","en":"Navratri, Navdurga"},"text":{"gu":"નવ રાત્રિ સુધી માતા દુર્ગાનાં નવ રૂપોની પૂજા થાય છે અને ગરબા રમાય છે.","hi":"नौ रातों तक माँ दुर्गा के नौ रूपों की पूजा होती है और गरबा खेला जाता है।","en":"For nine nights the nine forms of Goddess Durga are worshipped and garba is danced."},"shot":{"subject":"nine small diyas in a circle with a garba pot (garbo) at the centre","setting":"a festive red-orange background"}},{"id":"n10","n":10,"names":{"gu":"દસ","hi":"दस","en":"Ten"},"stands":{"gu":"દશાવતાર, દશેરા, દસ દિશા","hi":"दशावतार, दशहरा, दस दिशाएँ","en":"Dashavatar, Dussehra, ten directions"},"text":{"gu":"ભગવાન વિષ્ણુના દસ અવતાર છે. દશેરાએ સત્યની જીત ઊજવાય છે. દસ દિશાઓ આપણને ચારે તરફ જોવાનું શીખવે છે.","hi":"भगवान विष्णु के दस अवतार हैं। दशहरे पर सत्य की जीत मनाई जाती है। दस दिशाएँ हमें चारों ओर देखना सिखाती हैं।","en":"Lord Vishnu has ten avatars. Dussehra celebrates the victory of truth. Ten directions teach us to look all around."},"shot":{"subject":"ten tiny lotus petals arranged like a wheel","setting":"a bright sunrise background"}},{"id":"n12","n":12,"names":{"gu":"બાર","hi":"बारह","en":"Twelve"},"stands":{"gu":"બાર જ્યોતિર્લિંગ, બાર રાશિ","hi":"बारह ज्योतिर्लिंग, बारह राशि","en":"Twelve Jyotirlingas, twelve rashis"},"text":{"gu":"શિવજીનાં બાર પવિત્ર જ્યોતિર્લિંગ ભારતમાં છે, જેમ કે સોમનાથ અને કેદારનાથ. વર્ષમાં બાર મહિના પણ છે.","hi":"शिव जी के बारह पवित्र ज्योतिर्लिंग भारत में हैं, जैसे सोमनाथ और केदारनाथ। वर्ष में बारह महीने भी हैं।","en":"The twelve holy Jyotirlingas of Shiva are in India, such as Somnath and Kedarnath. A year also has twelve months."},"shot":{"subject":"twelve small glowing Shivlings arranged in a ring","setting":"a soft indigo background"}},{"id":"n18","n":18,"names":{"gu":"અઢાર","hi":"अठारह","en":"Eighteen"},"stands":{"gu":"ગીતાના 18 અધ્યાય, 18 પુરાણ","hi":"गीता के 18 अध्याय, 18 पुराण","en":"18 chapters of the Gita, 18 Puranas"},"text":{"gu":"ભગવદ્ગીતામાં 18 અધ્યાય છે. 18 મુખ્ય પુરાણ પણ છે, જે સારી વાર્તાઓ અને જ્ઞાન આપે છે.","hi":"भगवद्गीता में 18 अध्याय हैं। 18 मुख्य पुराण भी हैं, जो अच्छी कथाएँ और ज्ञान देते हैं।","en":"The Bhagavad Gita has 18 chapters. There are also 18 main Puranas that give good stories and wisdom."},"shot":{"subject":"an open Gita book with a small peacock feather on it","setting":"a warm saffron background"}},{"id":"n108","n":108,"names":{"gu":"એકસો આઠ","hi":"एक सौ आठ","en":"One hundred eight"},"stands":{"gu":"જપમાળાના 108 મણકા","hi":"जपमाला के 108 मनके","en":"108 beads of the japa mala"},"text":{"gu":"જપમાળામાં 108 મણકા હોય છે. તે ગણીને આપણે ભગવાનનું નામ ધ્યાનથી લઈએ છીએ.","hi":"जपमाला में 108 मनके होते हैं। उन्हें गिनकर हम ध्यान से भगवान का नाम लेते हैं।","en":"A japa mala has 108 beads. Counting them, we chant God's name with focus."},"shot":{"subject":"a rudraksh japa mala forming a circle","setting":"a quiet calm background"}}]},"deities":{"items":[{"id":"brahma","char":"brahma","vahan":{"gu":"હંસ","hi":"हंस","en":"Hans (swan)"},"loves":{"gu":"વેદ અને જ્ઞાન","hi":"वेद और ज्ञान","en":"The Vedas and knowledge"},"mantra":{"sa":"ॐ ब्रह्मणे नमः","say":{"gu":"ઓમ બ્રહ્મણે નમઃ","hi":"ॐ ब्रह्मणे नमः","en":"Om Brahmane Namah"},"meaning":{"gu":"સર્જનહાર બ્રહ્માજીને નમસ્કાર","hi":"सृजनकर्ता ब्रह्मा जी को नमस्कार","en":"Salutations to Brahma, the creator"}},"scenes":[{"id":1,"text":{"gu":"બ્રહ્માજી સૃષ્ટિના સર્જક છે. તેમને ચાર મુખ છે, જે ચાર વેદનું પ્રતીક છે.","hi":"ब्रह्मा जी सृष्टि के रचयिता हैं। उनके चार मुख हैं, जो चार वेदों के प्रतीक हैं।","en":"Brahma is the creator of the universe. His four faces stand for the four Vedas."},"shot":{"who":["brahma"],"setting":"a glowing golden lotus floating in a calm cosmic sky","action":"Brahma sits on the lotus with his four faces, hands holding a Veda book and a water pot","expression":"serene and wise","camera":"wide dreamy shot"}},{"id":2,"text":{"gu":"તેમનું વાહન હંસ છે. હંસ દૂધ અને પાણીને જુદાં કરી શકે છે, એટલે તે સારા-ખોટાને ઓળખવાની શીખ આપે છે.","hi":"उनका वाहन हंस है। हंस दूध और पानी को अलग कर सकता है, इसलिए वह अच्छे-बुरे को पहचानने की सीख देता है।","en":"His vehicle is the swan. A swan can separate milk from water, so it teaches us to tell good from bad."},"shot":{"who":["brahma"],"setting":"a calm lotus lake at sunrise","action":"Brahma rides a graceful white swan across the water","expression":"gentle smile","camera":"medium shot"}},{"id":3,"text":{"gu":"બ્રહ્માજીને જ્ઞાનના દેવ પણ કહે છે. તેમની પાસેથી આપણે નવું શીખવાની અને સુંદર વસ્તુઓ બનાવવાની પ્રેરણા લઈએ છીએ.","hi":"ब्रह्मा जी को ज्ञान के देवता भी कहते हैं। उनसे हम नया सीखने और सुंदर चीज़ें रचने की प्रेरणा लेते हैं।","en":"Brahma is also the god of knowledge. From him we take inspiration to learn new things and create beautiful ones."},"shot":{"who":["brahma"],"setting":"a heavenly study hall of floating palm-leaf scrolls","action":"Brahma gives a glowing book to a sage child who bows","expression":"Brahma: kind; child: eager","camera":"medium warm shot"}}],"lesson":{"gu":"બ્રહ્માજી આપણને શીખવે છે: નવું શીખો અને સારું રચો.","hi":"ब्रह्मा जी हमें सिखाते हैं: नया सीखो और अच्छा रचो।","en":"Brahma teaches us: keep learning and create something good."}},{"id":"vishnu","char":"vishnu","vahan":{"gu":"ગરુડ","hi":"गरुड़","en":"Garuda"},"loves":{"gu":"તુલસી અને શંખ","hi":"तुलसी और शंख","en":"Tulsi and the conch"},"mantra":{"sa":"ॐ नमो भगवते वासुदेवाय","say":{"gu":"ઓમ નમો ભગવતે વાસુદેવાય","hi":"ॐ नमो भगवते वासुदेवाय","en":"Om Namo Bhagavate Vasudevaya"},"meaning":{"gu":"ભગવાન વાસુદેવને નમસ્કાર","hi":"भगवान वासुदेव को नमस्कार","en":"Salutations to Lord Vasudeva"}},"scenes":[{"id":1,"text":{"gu":"ભગવાન વિષ્ણુ સૃષ્ટિનું પાલન કરે છે. તેમના ચાર હાથમાં શંખ, ચક્ર, ગદા અને કમળ છે.","hi":"भगवान विष्णु सृष्टि का पालन करते हैं। उनके चार हाथों में शंख, चक्र, गदा और कमल हैं।","en":"Lord Vishnu preserves the universe. In his four hands he holds a conch, discus, mace and lotus."},"shot":{"who":["vishnu"],"setting":"a calm milky ocean with a glowing lotus","action":"Vishnu rests on the serpent Sheshnag with Lakshmi massaging his feet, holding his four symbols","expression":"peaceful, kind","camera":"wide serene shot"}},{"id":2,"text":{"gu":"તેમનું વાહન ગરુડ છે, એક શક્તિશાળી પક્ષી. જ્યારે કોઈ સંકટમાં હોય ત્યારે વિષ્ણુ ગરુડ પર બેસી મદદ કરવા દોડે છે.","hi":"उनका वाहन गरुड़ है, एक शक्तिशाली पक्षी। जब कोई संकट में होता है तो विष्णु गरुड़ पर बैठकर मदद करने दौड़ते हैं।","en":"His vehicle is Garuda, a mighty bird. When someone is in trouble Vishnu rides Garuda to help."},"shot":{"who":["vishnu"],"setting":"the sky above green hills at sunrise","action":"Vishnu rides a great golden eagle-like Garuda over hills","expression":"focused and caring","camera":"wide aerial shot"}},{"id":3,"text":{"gu":"જ્યારે દુનિયામાં અધર્મ વધે ત્યારે વિષ્ણુ અવતાર લે છે. રામ અને કૃષ્ણ તેમના જ અવતાર છે.","hi":"जब दुनिया में अधर्म बढ़ता है तब विष्णु अवतार लेते हैं। राम और कृष्ण उन्हीं के अवतार हैं।","en":"When adharma grows in the world, Vishnu takes an avatar. Ram and Krishna are his avatars."},"shot":{"who":["vishnu","ram","krishna"],"setting":"a glowing cloud above earth","action":"Vishnu blesses with raised hand while soft images of Ram and Krishna glow beside him","expression":"calm","camera":"medium divine shot"}}],"lesson":{"gu":"વિષ્ણુ ભગવાન આપણને શીખવે છે: બધાનું ધ્યાન રાખો અને જરૂર પડે ત્યારે મદદ કરો.","hi":"भगवान विष्णु हमें सिखाते हैं: सबका ध्यान रखो और ज़रूरत पड़ने पर मदद करो।","en":"Lord Vishnu teaches us: care for all and help when needed."}},{"id":"shiva","char":"shiva","vahan":{"gu":"નંદી બળદ","hi":"नंदी बैल","en":"Nandi the bull"},"loves":{"gu":"બિલ્વપત્ર અને રુદ્રાક્ષ","hi":"बेलपत्र और रुद्राक्ष","en":"Bilva leaves and rudraksh"},"mantra":{"sa":"ॐ नमः शिवाय","say":{"gu":"ઓમ નમઃ શિવાય","hi":"ॐ नमः शिवाय","en":"Om Namah Shivaya"},"meaning":{"gu":"કલ્યાણકારી શિવને નમસ્કાર","hi":"कल्याणकारी शिव को नमस्कार","en":"Salutations to Shiva, the giver of good"}},"scenes":[{"id":1,"text":{"gu":"ભગવાન શિવ કૈલાસ પર્વત પર ધ્યાન કરે છે. તેમને મહાદેવ અને ભોલેનાથ પણ કહે છે કારણ કે તેઓ ખૂબ ભોળા છે.","hi":"भगवान शिव कैलाश पर्वत पर ध्यान करते हैं। उन्हें महादेव और भोलेनाथ भी कहते हैं क्योंकि वे बहुत भोले हैं।","en":"Lord Shiva meditates on Mount Kailash. He is also called Mahadev and Bholenath because he is so innocent-hearted."},"shot":{"who":["shiva"],"setting":"snowy Kailash peaks at dawn","action":"Shiva sits in meditation with closed eyes, a crescent moon on his head and the Ganga in his hair","expression":"deeply peaceful","camera":"wide majestic shot"}},{"id":2,"text":{"gu":"શિવજીના હાથમાં ત્રિશૂલ અને ડમરુ છે. ગળામાં નાગ, માથે ચંદ્ર અને જટામાં ગંગા છે.","hi":"शिव जी के हाथ में त्रिशूल और डमरू है। गले में नाग, माथे पर चंद्र और जटा में गंगा है।","en":"Shiva holds a trident and a damru. He has a snake around his neck, a moon on his head and the Ganga in his hair."},"shot":{"who":["shiva"],"setting":"a rocky terrace on Kailash","action":"Shiva plays the damru with a gentle smile while Nandi sits near","expression":"gentle joy","camera":"medium shot"}},{"id":3,"text":{"gu":"શિવજીએ સમુદ્રમંથન વખતે નીકળેલું વિષ પોતે પી લીધું અને બધાની રક્ષા કરી. એટલે તેમનું ગળું નીલું થયું અને તે ‘નીલકંઠ’ કહેવાયા.","hi":"शिव जी ने समुद्र मंथन के समय निकला विष स्वयं पी लिया और सबकी रक्षा की। इसलिए उनका गला नीला हुआ और वे ‘नीलकंठ’ कहलाए।","en":"During the churning of the ocean, Shiva drank the poison that came out and protected everyone. His throat turned blue and he became ‘Neelkanth’."},"shot":{"who":["shiva"],"setting":"a vast ocean with gods and demons holding a serpent rope in the distance","action":"Shiva calmly holds a cup of dark glow near his blue throat while gods bow with thanks","expression":"calm compassion","camera":"dramatic but gentle wide shot"}}],"lesson":{"gu":"શિવજી આપણને શીખવે છે: બીજાના ભલા માટે ત્યાગ કરો અને શાંત રહો.","hi":"शिव जी हमें सिखाते हैं: दूसरों के भले के लिए त्याग करो और शांत रहो।","en":"Lord Shiva teaches us: sacrifice for others' good and stay calm."}},{"id":"ganesh","char":"ganesh","vahan":{"gu":"ઉંદર (મૂષક)","hi":"चूहा (मूषक)","en":"Mouse (Mushak)"},"loves":{"gu":"મોદક અને દુર્વા","hi":"मोदक और दूर्वा","en":"Modak and durva grass"},"mantra":{"sa":"ॐ गं गणपतये नमः","say":{"gu":"ઓમ ગં ગણપતયે નમઃ","hi":"ॐ गं गणपतये नमः","en":"Om Gam Ganapataye Namah"},"meaning":{"gu":"વિઘ્નહર્તા ગણપતિને નમસ્કાર","hi":"विघ्नहर्ता गणपति को नमस्कार","en":"Salutations to Ganapati, remover of obstacles"}},"scenes":[{"id":1,"text":{"gu":"ગણેશજી શિવ-પાર્વતીના પુત્ર છે. તેમનું માથું હાથીનું અને પેટ મોટું છે. તેમને વિઘ્નહર્તા કહે છે.","hi":"गणेश जी शिव-पार्वती के पुत्र हैं। उनका सिर हाथी का और पेट बड़ा है। उन्हें विघ्नहर्ता कहते हैं।","en":"Ganesh is the son of Shiva and Parvati. He has an elephant head and a round tummy. He is called the remover of obstacles."},"shot":{"who":["ganesh"],"setting":"a decorated festival pavilion with flowers","action":"Ganesh sits happily on a lotus seat holding a modak and an axe-like goad","expression":"cheerful and kind","camera":"medium shot"}},{"id":2,"text":{"gu":"કોઈ પણ કામ શરૂ કરતાં પહેલાં આપણે ગણેશજીને યાદ કરીએ છીએ. તેમનું નાનું વાહન ઉંદર આપણને શીખવે છે કે નાના પણ મોટા કામ કરી શકે છે.","hi":"कोई भी काम शुरू करने से पहले हम गणेश जी को याद करते हैं। उनका छोटा वाहन चूहा सिखाता है कि छोटे भी बड़े काम कर सकते हैं।","en":"Before starting any task we remember Ganesh. His small vehicle, the mouse, teaches that even the small can do great things."},"shot":{"who":["ganesh"],"setting":"a school-going child's desk with books","action":"a child folds hands before a tiny Ganesh idol while a small mouse watches","expression":"child: hopeful; Ganesh: warm","camera":"medium shot"}},{"id":3,"text":{"gu":"ગણેશ ચતુર્થીએ ઘરે ગણપતિ બાપ્પાને લાવીને પૂજા કરે છે, મોદક ધરાવે છે અને ‘ગણપતિ બાપ્પા મોરયા’ બોલીને વિદાય આપે છે.","hi":"गणेश चतुर्थी पर घर में गणपति बप्पा को लाकर पूजा करते हैं, मोदक चढ़ाते हैं और ‘गणपति बप्पा मोरया’ बोलकर विदा करते हैं।","en":"On Ganesh Chaturthi people bring Ganpati home, worship him, offer modaks and bid farewell saying ‘Ganpati Bappa Morya’."},"shot":{"who":["ganesh"],"setting":"a festive street procession with drums and flowers","action":"Ganesh idol is carried joyfully by happy children and families","expression":"all: joyful","camera":"wide festive shot"}}],"lesson":{"gu":"ગણેશજી આપણને શીખવે છે: બુદ્ધિથી કામ કરો અને અવરોધથી ડરો નહીં.","hi":"गणेश जी हमें सिखाते हैं: बुद्धि से काम करो और बाधा से डरो नहीं।","en":"Ganesh teaches us: use your wisdom and do not fear obstacles."}},{"id":"hanuman","char":"hanuman","vahan":{"gu":"વાહન નથી, તેઓ પોતે ઊડી શકે છે","hi":"वाहन नहीं, वे स्वयं उड़ सकते हैं","en":"No vehicle — he can fly himself"},"loves":{"gu":"રામનું નામ અને લાડુ","hi":"राम का नाम और लड्डू","en":"Ram's name and laddu"},"mantra":{"sa":"ॐ हनुमते नमः","say":{"gu":"ઓમ હનુમતે નમઃ","hi":"ॐ हनुमते नमः","en":"Om Hanumate Namah"},"meaning":{"gu":"બળ અને ભક્તિવાળા હનુમાનજીને નમસ્કાર","hi":"बल और भक्ति वाले हनुमान जी को नमस्कार","en":"Salutations to Hanuman, full of strength and devotion"}},"scenes":[{"id":1,"text":{"gu":"હનુમાનજી પવનદેવના પુત્ર છે અને અંજની માતાના લાડલા. નાનપણમાં તેમણે સૂર્યને ફળ સમજી પકડવા છલાંગ મારી હતી.","hi":"हनुमान जी पवनदेव के पुत्र हैं और अंजनी माता के लाड़ले। बचपन में उन्होंने सूर्य को फल समझकर पकड़ने के लिए छलांग लगाई थी।","en":"Hanuman is the son of the Wind God and the darling of Mother Anjani. As a child he leapt up to catch the Sun, thinking it was a fruit."},"shot":{"who":["hanuman"],"setting":"a sunrise sky above green hills","action":"baby Hanuman leaps joyfully towards the golden Sun with outstretched hands","expression":"pure curious joy","camera":"wide playful shot"}},{"id":2,"text":{"gu":"હનુમાનજી શ્રીરામના પરમ ભક્ત છે. તેમણે સીતાજીને શોધ્યાં અને સંજીવની બુટ્ટી લાવ્યા.","hi":"हनुमान जी श्रीराम के परम भक्त हैं। उन्होंने सीता जी को खोजा और संजीवनी बूटी लाए।","en":"Hanuman is Shri Ram's greatest devotee. He found Sita and brought the Sanjeevani herb."},"shot":{"who":["hanuman","ram"],"setting":"a seashore at sunrise","action":"Hanuman bows to Ram with folded hands, Ram places a hand on his head","expression":"Hanuman: devoted; Ram: loving","camera":"medium warm shot"}},{"id":3,"text":{"gu":"તેઓ ખૂબ બળવાન હોવા છતાં નમ્ર છે. એક સાથે ‘જય શ્રીરામ’ બોલવાથી આપણને હિંમત અને શાંતિ મળે છે.","hi":"वे बहुत बलवान होने पर भी विनम्र हैं। साथ मिलकर ‘जय श्रीराम’ बोलने से हमें साहस और शांति मिलती है।","en":"Despite his great strength he is humble. Saying ‘Jai Shri Ram’ together gives us courage and peace."},"shot":{"who":["hanuman"],"setting":"a village Hanuman temple at dusk","action":"children chant with folded hands while Hanuman's statue glows softly","expression":"calm courage","camera":"medium shot"}}],"lesson":{"gu":"હનુમાનજી આપણને શીખવે છે: બળવાન હો તો પણ નમ્ર રહો અને ભક્તિથી સેવા કરો.","hi":"हनुमान जी हमें सिखाते हैं: बलवान होकर भी विनम्र रहो और भक्ति से सेवा करो।","en":"Hanuman teaches us: stay humble even when strong and serve with devotion."}},{"id":"kartikeya","char":"kartikeya","vahan":{"gu":"મોર","hi":"मोर","en":"Peacock"},"loves":{"gu":"વેલ (ભાલો) અને મોર","hi":"वेल (भाला) और मोर","en":"His spear (Vel) and peacock"},"mantra":{"sa":"ॐ शरवणभवाय नमः","say":{"gu":"ઓમ શરવણભવાય નમઃ","hi":"ॐ शरवणभवाय नमः","en":"Om Sharavanabhavaya Namah"},"meaning":{"gu":"કાર્તિકેયજીને નમસ્કાર","hi":"कार्तिकेय जी को नमस्कार","en":"Salutations to Lord Kartikeya"}},"scenes":[{"id":1,"text":{"gu":"કાર્તિકેયજી શિવ-પાર્વતીના પુત્ર છે. તેમને મુરુગન, સ્કંદ અને ષડાનન પણ કહે છે.","hi":"कार्तिकेय जी शिव-पार्वती के पुत्र हैं। उन्हें मुरुगन, स्कंद और षडानन भी कहते हैं।","en":"Kartikeya is the son of Shiva and Parvati. He is also called Murugan, Skanda and Shadanan."},"shot":{"who":["kartikeya"],"setting":"a hilltop temple at sunrise","action":"Kartikeya stands holding his spear with his peacock beside him","expression":"calm strength","camera":"wide heroic shot"}},{"id":2,"text":{"gu":"તેઓ દેવોના સેનાપતિ છે અને બહાદુરીથી ધર્મની રક્ષા કરે છે. તેમનું વાહન સુંદર મોર છે.","hi":"वे देवताओं के सेनापति हैं और वीरता से धर्म की रक्षा करते हैं। उनका वाहन सुंदर मोर है।","en":"He is the commander of the gods and protects dharma bravely. His vehicle is a beautiful peacock."},"shot":{"who":["kartikeya"],"setting":"a mountain path in golden light","action":"Kartikeya rides his peacock with his spear raised calmly","expression":"brave, kind","camera":"medium shot"}},{"id":3,"text":{"gu":"દક્ષિણ ભારતમાં કાર્તિકેયજીની મુરુગન રૂપે ખૂબ પૂજા થાય છે. તેઓ યુવાનોને હિંમત અને શિસ્ત શીખવે છે.","hi":"दक्षिण भारत में कार्तिकेय जी की मुरुगन रूप में बहुत पूजा होती है। वे युवाओं को साहस और अनुशासन सिखाते हैं।","en":"In South India Kartikeya is widely worshipped as Murugan. He teaches the young courage and discipline."},"shot":{"who":["kartikeya"],"setting":"a festive South Indian temple courtyard","action":"devotees carry decorated kavadi and bow to Kartikeya's idol","expression":"devotees: joyful","camera":"wide festive shot"}}],"lesson":{"gu":"કાર્તિકેયજી આપણને શીખવે છે: હિંમત અને શિસ્ત રાખો.","hi":"कार्तिकेय जी हमें सिखाते हैं: साहस और अनुशासन रखो।","en":"Kartikeya teaches us: have courage and discipline."}},{"id":"durga","char":"durga","vahan":{"gu":"સિંહ","hi":"सिंह","en":"Lion"},"loves":{"gu":"લાલ ફૂલ અને ચુંદડી","hi":"लाल फूल और चुनरी","en":"Red flowers and chunri"},"mantra":{"sa":"ॐ दुं दुर्गायै नमः","say":{"gu":"ઓમ દું દુર્ગાયૈ નમઃ","hi":"ॐ दुं दुर्गायै नमः","en":"Om Dum Durgayai Namah"},"meaning":{"gu":"માતા દુર્ગાને નમસ્કાર","hi":"माँ दुर्गा को नमस्कार","en":"Salutations to Mother Durga"}},"scenes":[{"id":1,"text":{"gu":"માતા દુર્ગા શક્તિનું રૂપ છે. તેમને દશ હાથ છે અને દરેક હાથમાં અલગ શસ્ત્ર છે.","hi":"माँ दुर्गा शक्ति का रूप हैं। उनके दस हाथ हैं और हर हाथ में अलग शस्त्र है।","en":"Mother Durga is the form of shakti. She has ten arms and each arm holds a different weapon."},"shot":{"who":["durga"],"setting":"a decorated Navratri pavilion","action":"Durga stands on her lion, calm and protective, with hands raised in blessing","expression":"calm strength","camera":"medium majestic shot"}},{"id":2,"text":{"gu":"તેમનું વાહન સિંહ છે. મહિષાસુર જેવા અધર્મી રાક્ષસને હરાવી તેમણે બધાને ભયમાંથી મુક્ત કર્યા.","hi":"उनका वाहन सिंह है। महिषासुर जैसे अधर्मी राक्षस को हराकर उन्होंने सबको भय से मुक्त किया।","en":"Her vehicle is the lion. She defeated the demon Mahishasur and freed everyone from fear."},"shot":{"who":["durga"],"setting":"a golden hall in the clouds","action":"Durga rides her lion; soft light overcomes a dark shadow (no violence)","expression":"fearless","camera":"wide dramatic shot"}},{"id":3,"text":{"gu":"નવરાત્રિમાં નવ દિવસ સુધી માતાની પૂજા અને ગરબા થાય છે. આપણે માતા પાસે હિંમત અને રક્ષાનો આશીર્વાદ માંગીએ છીએ.","hi":"नवरात्रि में नौ दिनों तक माँ की पूजा और गरबा होता है। हम माँ से साहस और रक्षा का आशीर्वाद माँगते हैं।","en":"During Navratri, Mother is worshipped for nine days with garba. We ask her for courage and protection."},"shot":{"who":["durga"],"setting":"a village Navratri ground with lamps and garba","action":"children dance garba in a circle around a glowing Durga idol","expression":"all: joyful","camera":"wide festive shot"}}],"lesson":{"gu":"માતા દુર્ગા આપણને શીખવે છે: સાચા માટે હિંમતથી ઊભા રહો.","hi":"माँ दुर्गा हमें सिखाती हैं: सही के लिए साहस से खड़े रहो।","en":"Mother Durga teaches us: stand up bravely for what is right."}},{"id":"lakshmi","char":"lakshmi","vahan":{"gu":"ઘુવડ (અને હાથી)","hi":"उल्लू (और हाथी)","en":"Owl (and elephants)"},"loves":{"gu":"કમળ અને સિક્કા","hi":"कमल और सिक्के","en":"Lotus and coins"},"mantra":{"sa":"ॐ महालक्ष्म्यै नमः","say":{"gu":"ઓમ મહાલક્ષ્મ્યૈ નમઃ","hi":"ॐ महालक्ष्म्यै नमः","en":"Om Mahalakshmyai Namah"},"meaning":{"gu":"માતા લક્ષ્મીને નમસ્કાર","hi":"माँ लक्ष्मी को नमस्कार","en":"Salutations to Mother Lakshmi"}},"scenes":[{"id":1,"text":{"gu":"માતા લક્ષ્મી ધન અને સમૃદ્ધિનાં દેવી છે. તેઓ કમળ પર બેસે છે અને ભગવાન વિષ્ણુનાં પત્ની છે.","hi":"माँ लक्ष्मी धन और समृद्धि की देवी हैं। वे कमल पर बैठती हैं और भगवान विष्णु की पत्नी हैं।","en":"Mother Lakshmi is the goddess of wealth and prosperity. She sits on a lotus and is Lord Vishnu's wife."},"shot":{"who":["lakshmi"],"setting":"a golden pond of lotuses","action":"Lakshmi sits on a lotus with golden coins flowing from her hand and elephants pouring water","expression":"gentle smile","camera":"wide golden shot"}},{"id":2,"text":{"gu":"દિવાળીએ લક્ષ્મી પૂજન થાય છે. ઘર સાફ કરીને દીવા પ્રગટાવાય છે જેથી લક્ષ્મીજી પ્રસન્ન થઈને ઘરમાં આવે.","hi":"दीवाली पर लक्ष्मी पूजन होता है। घर साफ़ करके दीप जलाए जाते हैं ताकि लक्ष्मी जी प्रसन्न होकर घर में आएँ।","en":"On Diwali Lakshmi puja is done. Homes are cleaned and lamps lit so that Lakshmi may happily come in."},"shot":{"who":["lakshmi"],"setting":"a clean decorated doorstep with rangoli","action":"a family places diyas and welcomes Lakshmi with folded hands","expression":"hopeful joy","camera":"medium festive shot"}},{"id":3,"text":{"gu":"સાચી સંપત્તિ ફક્ત પૈસા નથી, પણ મહેનત, પ્રમાણિકતા અને સંતોષ છે. લક્ષ્મીજી ત્યાં રહે છે જ્યાં સ્વચ્છતા અને પ્રેમ છે.","hi":"सच्ची संपत्ति केवल पैसा नहीं, बल्कि परिश्रम, ईमानदारी और संतोष है। लक्ष्मी जी वहाँ रहती हैं जहाँ स्वच्छता और प्रेम है।","en":"True wealth is not only money but hard work, honesty and contentment. Lakshmi lives where there is cleanliness and love."},"shot":{"who":["lakshmi"],"setting":"a happy home with a lit lamp","action":"Lakshmi blesses a child who shares sweets with neighbours","expression":"warm","camera":"medium shot"}}],"lesson":{"gu":"લક્ષ્મીજી આપણને શીખવે છે: મહેનત કરો, પ્રમાણિક રહો અને વહેંચીને ખાઓ.","hi":"लक्ष्मी जी हमें सिखाती हैं: परिश्रम करो, ईमानदार रहो और बाँटकर खाओ।","en":"Lakshmi teaches us: work hard, be honest and share."}},{"id":"saraswati","char":"saraswati","vahan":{"gu":"હંસ (અને મોર)","hi":"हंस (और मोर)","en":"Swan (and peacock)"},"loves":{"gu":"વીણા અને પુસ્તક","hi":"वीणा और पुस्तक","en":"Veena and books"},"mantra":{"sa":"ॐ ऐं सरस्वत्यै नमः","say":{"gu":"ઓમ ઐં સરસ્વત્યૈ નમઃ","hi":"ॐ ऐं सरस्वत्यै नमः","en":"Om Aim Saraswatyai Namah"},"meaning":{"gu":"વિદ્યાદેવી સરસ્વતીને નમસ્કાર","hi":"विद्या की देवी सरस्वती को नमस्कार","en":"Salutations to Saraswati, goddess of knowledge"}},"scenes":[{"id":1,"text":{"gu":"માતા સરસ્વતી વિદ્યા, સંગીત અને કલાનાં દેવી છે. તેઓ સફેદ સાડી પહેરી કમળ પર બેસે છે.","hi":"माँ सरस्वती विद्या, संगीत और कला की देवी हैं। वे सफ़ेद साड़ी पहनकर कमल पर बैठती हैं।","en":"Mother Saraswati is the goddess of knowledge, music and arts. She wears a white saree and sits on a lotus."},"shot":{"who":["saraswati"],"setting":"a calm white lotus lake at sunrise","action":"Saraswati plays the veena with a gentle smile and a swan beside her","expression":"serene","camera":"wide serene shot"}},{"id":2,"text":{"gu":"વસંત પંચમીએ બાળકો પુસ્તકો અને કલમની પૂજા કરે છે અને વિદ્યાનો આશીર્વાદ માંગે છે.","hi":"वसंत पंचमी पर बच्चे पुस्तकों और कलम की पूजा करते हैं और विद्या का आशीर्वाद माँगते हैं।","en":"On Vasant Panchami children worship their books and pens and ask for the blessing of knowledge."},"shot":{"who":["saraswati"],"setting":"a yellow-decorated classroom with flowers","action":"children place their books and pens before Saraswati's idol and fold hands","expression":"hopeful","camera":"medium shot"}},{"id":3,"text":{"gu":"હંસ આપણને શીખવે છે કે સાચું-ખોટું ઓળખવું, અને વીણા શીખવે છે કે સંગીતથી મન શાંત થાય છે.","hi":"हंस हमें सिखाता है कि सही-गलत पहचानना, और वीणा सिखाती है कि संगीत से मन शांत होता है।","en":"The swan teaches us to know right from wrong, and the veena teaches that music calms the mind."},"shot":{"who":["saraswati"],"setting":"a bright garden","action":"Saraswati teaches a child to play a simple tune on the veena","expression":"warm","camera":"medium shot"}}],"lesson":{"gu":"સરસ્વતીજી આપણને શીખવે છે: ખંતથી ભણો અને નમ્ર રહો.","hi":"सरस्वती जी हमें सिखाती हैं: लगन से पढ़ो और विनम्र रहो।","en":"Saraswati teaches us: study with focus and stay humble."}},{"id":"parvati","char":"uma","vahan":{"gu":"સિંહ","hi":"सिंह","en":"Lion"},"loves":{"gu":"શિવજી અને ગણેશજી","hi":"शिव जी और गणेश जी","en":"Shiva and Ganesh"},"mantra":{"sa":"ॐ पार्वत्यै नमः","say":{"gu":"ઓમ પાર્વત્યૈ નમઃ","hi":"ॐ पार्वत्यै नमः","en":"Om Parvatyai Namah"},"meaning":{"gu":"માતા પાર્વતીને નમસ્કાર","hi":"माँ पार्वती को नमस्कार","en":"Salutations to Mother Parvati"}},"scenes":[{"id":1,"text":{"gu":"માતા પાર્વતી પર્વતરાજ હિમાલયનાં પુત્રી છે. તેમણે કઠિન તપસ્યા કરી ભગવાન શિવને પામ્યાં.","hi":"माँ पार्वती पर्वतराज हिमालय की पुत्री हैं। उन्होंने कठिन तपस्या करके भगवान शिव को पाया।","en":"Mother Parvati is the daughter of the mountain king Himalaya. She won Lord Shiva through hard tapasya."},"shot":{"who":["uma"],"setting":"a quiet Himalayan forest","action":"Parvati meditates with folded hands under a tree, a soft glow around her","expression":"determined, calm","camera":"wide serene shot"}},{"id":2,"text":{"gu":"તેઓ ગણેશ અને કાર્તિકેયનાં માતા છે. માતાનો પ્રેમ ખૂબ ઊંડો અને નિઃસ્વાર્થ હોય છે.","hi":"वे गणेश और कार्तिकेय की माता हैं। माँ का प्रेम बहुत गहरा और निःस्वार्थ होता है।","en":"She is the mother of Ganesh and Kartikeya. A mother's love is deep and selfless."},"shot":{"who":["uma","ganesh"],"setting":"a warm Kailash home","action":"Parvati lovingly feeds little Ganesh a sweet","expression":"loving","camera":"medium shot"}},{"id":3,"text":{"gu":"નવરાત્રિમાં માતાનાં રૂપોની પૂજા થાય છે. પાર્વતીજી દયા, ધીરજ અને પ્રેમનું પ્રતીક છે.","hi":"नवरात्रि में माता के रूपों की पूजा होती है। पार्वती जी दया, धैर्य और प्रेम का प्रतीक हैं।","en":"During Navratri the forms of the Mother are worshipped. Parvati stands for kindness, patience and love."},"shot":{"who":["uma"],"setting":"a decorated temple at dusk","action":"devotees offer flowers to Parvati's idol with folded hands","expression":"peaceful","camera":"medium shot"}}],"lesson":{"gu":"પાર્વતીજી આપણને શીખવે છે: ધીરજથી મહેનત કરો અને પ્રેમથી પરિવારને જોડી રાખો.","hi":"पार्वती जी हमें सिखाती हैं: धैर्य से परिश्रम करो और प्रेम से परिवार को जोड़े रखो।","en":"Parvati teaches us: work with patience and hold your family together with love."}},{"id":"sita","char":"sita","vahan":{"gu":"વાહન નથી, ધરતીમાતાનાં પુત્રી","hi":"वाहन नहीं, धरती माता की पुत्री","en":"No vehicle — a daughter of Mother Earth"},"loves":{"gu":"ફૂલો અને બગીચો","hi":"फूल और बगीचा","en":"Flowers and gardens"},"mantra":{"sa":"ॐ सीतायै नमः","say":{"gu":"ઓમ સીતાયૈ નમઃ","hi":"ॐ सीतायै नमः","en":"Om Sitayai Namah"},"meaning":{"gu":"માતા સીતાને નમસ્કાર","hi":"माँ सीता को नमस्कार","en":"Salutations to Mother Sita"}},"scenes":[{"id":1,"text":{"gu":"સીતાજી રાજા જનકની પુત્રી અને શ્રીરામનાં પત્ની છે. તેમને ધરતીમાંથી પ્રાપ્ત થયાં એટલે તેમને ભૂમિજા કહે છે.","hi":"सीता जी राजा जनक की पुत्री और श्रीराम की पत्नी हैं। वे धरती से प्राप्त हुईं इसलिए उन्हें भूमिजा कहते हैं।","en":"Sita is the daughter of King Janak and the wife of Shri Ram. Found from the earth, she is called Bhumija."},"shot":{"who":["sita"],"setting":"a green farm field at dawn","action":"Sita smiles holding a flower, standing in a field","expression":"gentle","camera":"medium warm shot"}},{"id":2,"text":{"gu":"સીતાજીએ રામ સાથે વનમાં જઈ સાદગીથી રહી બતાવ્યું કે પ્રેમ અને વફાદારી સૌથી મોટી સંપત્તિ છે.","hi":"सीता जी ने राम के साथ वन जाकर सादगी से रहकर दिखाया कि प्रेम और निष्ठा सबसे बड़ी संपत्ति हैं।","en":"By going to the forest with Ram and living simply, Sita showed that love and loyalty are the greatest wealth."},"shot":{"who":["sita","ram"],"setting":"a forest hut","action":"Sita and Ram sit peacefully outside their hut","expression":"content","camera":"medium cosy shot"}},{"id":3,"text":{"gu":"અશોક વાટિકામાં સીતાજીએ ધીરજ ન ગુમાવી. તેઓ આપણને મુશ્કેલીમાં શાંત અને મજબૂત રહેવાનું શીખવે છે.","hi":"अशोक वाटिका में सीता जी ने धैर्य नहीं खोया। वे हमें कठिनाई में शांत और मज़बूत रहना सिखाती हैं।","en":"In Ashok Vatika Sita did not lose patience. She teaches us to stay calm and strong in difficulty."},"shot":{"who":["sita"],"setting":"a quiet garden at dusk","action":"Sita sits with folded hands and a soft glow of hope","expression":"calm courage","camera":"medium shot"}}],"lesson":{"gu":"સીતાજી આપણને શીખવે છે: ધીરજ અને સત્ય સાથે મજબૂત રહો.","hi":"सीता जी हमें सिखाती हैं: धैर्य और सत्य के साथ मज़बूत रहो।","en":"Sita teaches us: stay strong with patience and truth."}},{"id":"radha","char":"radha","vahan":{"gu":"વાહન નથી, કૃષ્ણભક્તિ જ સાથી","hi":"वाहन नहीं, कृष्णभक्ति ही साथी","en":"No vehicle — devotion to Krishna is her companion"},"loves":{"gu":"કૃષ્ણની વાંસળી અને ફૂલ","hi":"कृष्ण की बाँसुरी और फूल","en":"Krishna's flute and flowers"},"mantra":{"sa":"ॐ राधिकायै नमः","say":{"gu":"ઓમ રાધિકાયૈ નમઃ","hi":"ॐ राधिकायै नमः","en":"Om Radhikayai Namah"},"meaning":{"gu":"શ્રી રાધાજીને નમસ્કાર","hi":"श्री राधा जी को नमस्कार","en":"Salutations to Shri Radha"}},"scenes":[{"id":1,"text":{"gu":"રાધાજી શ્રીકૃષ્ણનાં પરમ ભક્ત છે. તેમના પ્રેમમાં સ્વાર્થ ન હતો, માત્ર ભક્તિ હતી.","hi":"राधा जी श्रीकृष्ण की परम भक्त हैं। उनके प्रेम में स्वार्थ नहीं था, केवल भक्ति थी।","en":"Radha is Shri Krishna's supreme devotee. Her love had no selfishness, only devotion."},"shot":{"who":["radha","krishna"],"setting":"a Vrindavan grove with blooming trees","action":"Radha and young Krishna stand together under a tree, Krishna plays his flute","expression":"both: joyful","camera":"medium warm shot"}},{"id":2,"text":{"gu":"વૃંદાવનમાં રાધા-કૃષ્ણ સાથે રમતા, ગાતા અને નાચતા. રાસલીલા ભક્તિ અને આનંદનું સુંદર રૂપ છે.","hi":"वृंदावन में राधा-कृष्ण साथ खेलते, गाते और नाचते थे। रासलीला भक्ति और आनंद का सुंदर रूप है।","en":"In Vrindavan, Radha and Krishna played, sang and danced together. The raas is a beautiful form of devotion and joy."},"shot":{"who":["radha","krishna"],"setting":"a moonlit Vrindavan grove","action":"Radha, Krishna and friends dance in a circle with gentle steps","expression":"all: joyful","camera":"wide musical shot"}},{"id":3,"text":{"gu":"‘રાધે રાધે’ બોલવું એટલે પ્રેમ અને શાંતિને યાદ કરવી. રાધાજી આપણને શીખવે છે કે સાચો પ્રેમ નિઃસ્વાર્થ હોય છે.","hi":"‘राधे राधे’ बोलना यानी प्रेम और शांति को याद करना। राधा जी हमें सिखाती हैं कि सच्चा प्रेम निःस्वार्थ होता है।","en":"Saying ‘Radhe Radhe’ is remembering love and peace. Radha teaches us that true love is selfless."},"shot":{"who":["radha"],"setting":"a village temple at sunset","action":"children greet each other with ‘Radhe Radhe’ and folded hands","expression":"happy","camera":"medium shot"}}],"lesson":{"gu":"રાધાજી આપણને શીખવે છે: સ્વાર્થ વગર પ્રેમ અને ભક્તિ કરો.","hi":"राधा जी हमें सिखाती हैं: निःस्वार्थ प्रेम और भक्ति करो।","en":"Radha teaches us: love and devote yourself without selfishness."}}]},"avatars":{"items":[{"id":"matsya","char":"matsya","order":1,"yuga":{"gu":"સત્યયુગ","hi":"सत्ययुग","en":"Satya Yuga"},"form":{"gu":"માછલી","hi":"मछली","en":"Fish"},"scenes":[{"id":1,"text":{"gu":"પ્રલય આવવાનો હતો ત્યારે નાની માછલીએ રાજા મનુ પાસે મદદ માંગી. મનુએ તેને પ્રેમથી બચાવી.","hi":"जब प्रलय आने वाला था तब एक छोटी मछली ने राजा मनु से मदद माँगी। मनु ने उसे प्रेम से बचाया।","en":"When a great flood was about to come, a small fish asked King Manu for help. Manu lovingly saved it."},"shot":{"who":["matsya"],"setting":"a river bank at sunrise","action":"King Manu (simple saffron robes, sage-like) cups a tiny glowing golden fish in his hands","expression":"Manu: kind; fish: trusting","camera":"medium gentle shot"}},{"id":2,"text":{"gu":"માછલી મોટી થતી ગઈ અને પછી તે ભગવાન વિષ્ણુનો અવતાર બની. તેણે મનુને હોડી બનાવવા કહ્યું.","hi":"मछली बड़ी होती गई और फिर भगवान विष्णु का अवतार निकली। उसने मनु से नाव बनाने को कहा।","en":"The fish grew bigger and turned out to be Lord Vishnu's avatar. It told Manu to build a boat."},"shot":{"who":["matsya"],"setting":"a vast ocean at dawn","action":"a huge golden fish with a horn rises from the sea while Manu looks in awe on a boat","expression":"Manu: wonder","camera":"wide magical shot"}},{"id":3,"text":{"gu":"મત્સ્ય ભગવાને વેદ અને સપ્તર્ષિઓને હોડીમાં બચાવ્યા. નવી સૃષ્ટિ ફરી શરૂ થઈ.","hi":"मत्स्य भगवान ने वेदों और सप्तर्षियों को नाव में बचाया। नई सृष्टि फिर आरंभ हुई।","en":"Lord Matsya saved the Vedas and the seven sages in the boat. A new creation began."},"shot":{"who":["matsya"],"setting":"a calm sea at sunrise","action":"the boat with sages is gently pulled by the golden fish, a rainbow overhead","expression":"hopeful","camera":"wide hopeful shot"}}],"lesson":{"gu":"મત્સ્ય અવતાર શીખવે છે: નાનાની મદદ કરો, ભગવાન ફળ આપશે.","hi":"मत्स्य अवतार सिखाता है: छोटों की मदद करो, ईश्वर फल देंगे।","en":"Matsya teaches us: help the small, and God will reward."}},{"id":"kurma","char":"kurma","order":2,"yuga":{"gu":"સત્યયુગ","hi":"सत्ययुग","en":"Satya Yuga"},"form":{"gu":"કાચબો","hi":"कछुआ","en":"Tortoise"},"scenes":[{"id":1,"text":{"gu":"દેવો અને અસુરો સમુદ્રમંથન કરતા હતા. મંદરાચલ પર્વત મથાણી હતો પણ તે સમુદ્રમાં ડૂબવા લાગ્યો.","hi":"देवता और असुर समुद्र मंथन कर रहे थे। मंदराचल पर्वत मथानी था पर वह समुद्र में डूबने लगा।","en":"Gods and asuras were churning the ocean. Mount Mandar was the churning rod but it began to sink."},"shot":{"who":["kurma"],"setting":"a vast ocean with a big mountain","action":"gods and asuras pull a snake-rope around a mountain as it tilts","expression":"gods: worried","camera":"wide shot"}},{"id":2,"text":{"gu":"ભગવાન વિષ્ણુએ કાચબાનું રૂપ લીધું અને પર્વતને પોતાની પીઠ પર ઊંચકી લીધો.","hi":"भगवान विष्णु ने कछुए का रूप लिया और पर्वत को अपनी पीठ पर उठा लिया।","en":"Lord Vishnu took the form of a tortoise and lifted the mountain on his back."},"shot":{"who":["kurma"],"setting":"the ocean at dawn","action":"a giant golden tortoise holds the mountain steady on its shell","expression":"calm strong","camera":"dramatic wide shot"}},{"id":3,"text":{"gu":"મંથનથી અમૃત, લક્ષ્મીજી અને ધન્વંતરિ જેવા રત્નો નીકળ્યા. બધાને સંયમ અને સાથ કામ કરવાનું શીખવા મળ્યું.","hi":"मंथन से अमृत, लक्ष्मी जी और धन्वंतरि जैसे रत्न निकले। सबको संयम और साथ मिलकर काम करने की सीख मिली।","en":"From the churning came nectar, Lakshmi and Dhanvantari. Everyone learned patience and teamwork."},"shot":{"who":["kurma","lakshmi"],"setting":"a glowing sea with lotus","action":"Lakshmi rises from the sea on a lotus as gods bow with joy","expression":"all: joyful","camera":"wide divine shot"}}],"lesson":{"gu":"કૂર્મ અવતાર શીખવે છે: ધીરજ અને સહકારથી મોટા કામ થાય છે.","hi":"कूर्म अवतार सिखाता है: धैर्य और सहयोग से बड़े काम होते हैं।","en":"Kurma teaches us: patience and teamwork accomplish great things."}},{"id":"varaha","char":"varaha","order":3,"yuga":{"gu":"સત્યયુગ","hi":"सत्ययुग","en":"Satya Yuga"},"form":{"gu":"વરાહ (ભૂંડ)","hi":"वराह (सूअर)","en":"Varaha (boar)"},"scenes":[{"id":1,"text":{"gu":"એક અસુર હિરણ્યાક્ષ પૃથ્વીને સમુદ્રમાં લઈ ગયો. બધા દેવો ચિંતામાં આવ્યા.","hi":"एक असुर हिरण्याक्ष पृथ्वी को समुद्र में ले गया। सब देवता चिंतित हुए।","en":"An asura named Hiranyaksha took the Earth into the ocean. The gods were worried."},"shot":{"who":["varaha"],"setting":"a deep cosmic sea","action":"a small glowing Earth lies at the bottom of a clear ocean as gods look from above","expression":"worried","camera":"wide shot"}},{"id":2,"text":{"gu":"ભગવાન વિષ્ણુએ વરાહનું રૂપ લીધું અને સમુદ્રમાં ડૂબકી મારી. તેમણે પૃથ્વીને પોતાના દાંત પર ઊંચકી.","hi":"भगवान विष्णु ने वराह का रूप लिया और समुद्र में गोता लगाया। उन्होंने पृथ्वी को अपने दाँतों पर उठा लिया।","en":"Lord Vishnu took the form of Varaha and dived into the ocean. He lifted the Earth on his tusks."},"shot":{"who":["varaha"],"setting":"the ocean surface at sunrise","action":"a great golden boar carries a small glowing Earth on its tusks","expression":"strong and gentle","camera":"dramatic shot"}},{"id":3,"text":{"gu":"પૃથ્વી ફરી પોતાની જગ્યાએ સ્થાપિત થઈ. બધા જીવોએ આનંદ કર્યો અને ભગવાનનો આભાર માન્યો.","hi":"पृथ्वी फिर अपने स्थान पर स्थापित हुई। सब जीवों ने आनंद मनाया और भगवान का धन्यवाद किया।","en":"The Earth was set back in her place. All beings rejoiced and thanked God."},"shot":{"who":["varaha"],"setting":"a blooming earth","action":"animals and people bow with thanks around Varaha","expression":"happy","camera":"wide shot"}}],"lesson":{"gu":"વરાહ અવતાર શીખવે છે: પૃથ્વીની રક્ષા કરવી એ આપણી ફરજ છે.","hi":"वराह अवतार सिखाता है: पृथ्वी की रक्षा करना हमारा कर्तव्य है।","en":"Varaha teaches us: protecting the Earth is our duty."}},{"id":"narasimha","char":"narasimha","order":4,"yuga":{"gu":"સત્યયુગ","hi":"सत्ययुग","en":"Satya Yuga"},"form":{"gu":"અડધા સિંહ, અડધા માનવ","hi":"आधे सिंह, आधे मानव","en":"Half lion, half man"},"scenes":[{"id":1,"text":{"gu":"નાનકડા ભક્ત પ્રહ્લાદ ભગવાન વિષ્ણુનું નામ લેતા અને તેમના પિતા હિરણ્યકશિપુ આ પસંદ કરતા ન હતા.","hi":"नन्हे भक्त प्रह्लाद भगवान विष्णु का नाम लेते थे और उनके पिता हिरण्यकशिपु को यह पसंद नहीं था।","en":"Little Prahlad chanted Lord Vishnu's name and his father Hiranyakashipu did not like it."},"shot":{"who":["prahlad"],"setting":"a royal court","action":"Prahlad stands steady with folded hands before his father","expression":"fearless","camera":"medium shot"}},{"id":2,"text":{"gu":"હિરણ્યકશિપુએ પૂછ્યું, “તારો ભગવાન ક્યાં છે?” પ્રહ્લાદે કહ્યું, “તે બધે છે, આ થાંભલામાં પણ.”","hi":"हिरण्यकशिपु ने पूछा, “तेरा भगवान कहाँ है?” प्रह्लाद ने कहा, “वे हर जगह हैं, इस खंभे में भी।”","en":"Hiranyakashipu asked, “Where is your God?” Prahlad said, “He is everywhere, even in this pillar.”"},"shot":{"who":["prahlad"],"setting":"a grand hall with a pillar","action":"Prahlad points calmly to a stone pillar","expression":"calm faith","camera":"medium shot"}},{"id":3,"text":{"gu":"થાંભલામાંથી નૃસિંહ ભગવાન પ્રગટ થયા અને ભક્તની રક્ષા કરી. સાંજના સમયે, બારણાની વચ્ચે, ન તો માણસ ન પશુ — એ રીતે અસુરનો અંત થયો.","hi":"खंभे से नृसिंह भगवान प्रकट हुए और भक्त की रक्षा की। संध्या के समय, द्वार की चौखट पर, न मनुष्य न पशु — इस तरह असुर का अंत हुआ।","en":"Lord Narasimha appeared from the pillar and protected the devotee. At twilight, at the doorway, neither man nor beast — the asura met his end."},"shot":{"who":["narasimha","prahlad"],"setting":"a hall with golden twilight light","action":"Narasimha appears from the pillar in a burst of light, Prahlad bows safe","expression":"Prahlad: peaceful","camera":"dramatic gentle shot (no violence)"}}],"lesson":{"gu":"નૃસિંહ અવતાર શીખવે છે: સાચા ભક્તની ભગવાન હંમેશાં રક્ષા કરે છે.","hi":"नृसिंह अवतार सिखाता है: सच्चे भक्त की भगवान सदा रक्षा करते हैं।","en":"Narasimha teaches us: God always protects a true devotee."}},{"id":"vamana","char":"vamana","order":5,"yuga":{"gu":"ત્રેતાયુગ","hi":"त्रेतायुग","en":"Treta Yuga"},"form":{"gu":"નાના બ્રાહ્મણ બાળક","hi":"छोटे ब्राह्मण बालक","en":"Small brahmin boy"},"scenes":[{"id":1,"text":{"gu":"રાજા બલિ દાનવીર અને શક્તિશાળી હતા પણ તેમને અભિમાન આવ્યું. દેવો ચિંતામાં આવ્યા.","hi":"राजा बलि दानवीर और शक्तिशाली थे पर उन्हें अभिमान आ गया। देवता चिंतित हुए।","en":"King Bali was generous and powerful but he became proud. The gods were worried."},"shot":{"who":["vamana"],"setting":"a grand yajna hall","action":"King Bali sits generously giving gifts to many","expression":"proud","camera":"wide shot"}},{"id":2,"text":{"gu":"ભગવાન વિષ્ણુ નાના વામન બનીને બલિ પાસે ગયા અને ત્રણ પગલાં જમીન માંગી. બલિએ હસીને હા કહી.","hi":"भगवान विष्णु छोटे वामन बनकर बलि के पास गए और तीन पग भूमि माँगी। बलि ने हँसकर हाँ कह दी।","en":"Lord Vishnu came to Bali as small Vamana and asked for three steps of land. Bali smilingly agreed."},"shot":{"who":["vamana"],"setting":"the yajna hall","action":"a small boy with an umbrella and a staff stands before the king","expression":"humble","camera":"medium shot"}},{"id":3,"text":{"gu":"વામન વિશાળ થયા. એક પગલે પૃથ્વી, બીજાએ આકાશ માપ્યું અને ત્રીજું પગલું બલિના માથે મૂક્યું. નમ્ર બલિ સુતલ લોકના રાજા બન્યા.","hi":"वामन विशाल हो गए। एक पग में पृथ्वी, दूसरे में आकाश नापा और तीसरा पग बलि के मस्तक पर रखा। विनम्र बलि सुतल लोक के राजा बने।","en":"Vamana grew huge. With one step he measured the earth, with the second the sky, and he placed the third on Bali's head. The humble Bali became ruler of the Sutal Loka."},"shot":{"who":["vamana"],"setting":"a cosmic sky","action":"a giant golden Vamana strides across the sky as Bali bows","expression":"Bali: humble","camera":"wide divine shot"}}],"lesson":{"gu":"વામન અવતાર શીખવે છે: અભિમાન ન કરો, નમ્ર રહો.","hi":"वामन अवतार सिखाता है: अभिमान मत करो, विनम्र रहो।","en":"Vamana teaches us: do not be proud; stay humble."}},{"id":"parshurama","char":"parshurama","order":6,"yuga":{"gu":"ત્રેતાયુગ","hi":"त्रेतायुग","en":"Treta Yuga"},"form":{"gu":"ઋષિ યોદ્ધા, ફરસીધારી","hi":"ऋषि योद्धा, फरसाधारी","en":"Sage-warrior with an axe"},"scenes":[{"id":1,"text":{"gu":"પરશુરામ ઋષિ જમદગ્નિ અને રેણુકાના પુત્ર હતા. નાનપણથી જ તેઓ બહુ તેજસ્વી અને માતા-પિતાના આજ્ઞાકારી હતા.","hi":"परशुराम ऋषि जमदग्नि और रेणुका के पुत्र थे। बचपन से ही वे बहुत तेजस्वी और माता-पिता के आज्ञाकारी थे।","en":"Parshurama was the son of sage Jamadagni and Renuka. From childhood he was bright and obeyed his parents."},"shot":{"who":["parshurama"],"setting":"a forest hermitage","action":"young Parshurama bows to his parents","expression":"respectful","camera":"medium shot"}},{"id":2,"text":{"gu":"ભગવાન શિવ પાસેથી તેમને ફરસી મળી. તેમણે અન્યાય કરનારા અહંકારી રાજાઓ સામે ધર્મની રક્ષા કરી.","hi":"भगवान शिव से उन्हें फरसा मिला। उन्होंने अन्याय करने वाले अहंकारी राजाओं के विरुद्ध धर्म की रक्षा की।","en":"He received an axe from Lord Shiva. He protected dharma against proud kings who did injustice."},"shot":{"who":["parshurama","shiva"],"setting":"a Himalayan hermitage","action":"Shiva hands a shining axe to Parshurama who bows","expression":"humble","camera":"medium shot"}},{"id":3,"text":{"gu":"પરશુરામ ચિરંજીવી મનાય છે. તેમણે શ્રીરામ અને કૃષ્ણ બંનેને મળીને આશીર્વાદ આપ્યા એવું કહેવાય છે.","hi":"परशुराम चिरंजीवी माने जाते हैं। कहा जाता है कि उन्होंने श्रीराम और कृष्ण दोनों से मिलकर आशीर्वाद दिया।","en":"Parshurama is believed to be immortal. It is said he met and blessed both Shri Ram and Krishna."},"shot":{"who":["parshurama","ram"],"setting":"a green mountain","action":"Parshurama blesses Ram with a raised hand","expression":"wise","camera":"medium shot"}}],"lesson":{"gu":"પરશુરામ શીખવે છે: અન્યાય સામે ઊભા રહો, માતા-પિતાની આજ્ઞા માનો.","hi":"परशुराम सिखाते हैं: अन्याय के विरुद्ध खड़े रहो, माता-पिता की आज्ञा मानो।","en":"Parshurama teaches us: stand against injustice; obey your parents."}},{"id":"ram","char":"ram","order":7,"yuga":{"gu":"ત્રેતાયુગ","hi":"त्रेतायुग","en":"Treta Yuga"},"form":{"gu":"આદર્શ રાજકુમાર","hi":"आदर्श राजकुमार","en":"The ideal prince"},"scenes":[{"id":1,"text":{"gu":"અયોધ્યામાં શ્રીરામનો જન્મ થયો. તેઓ સત્ય અને ધર્મ પર ચાલતા હતા એટલે ‘મર્યાદા પુરુષોત્તમ’ કહેવાયા.","hi":"अयोध्या में श्रीराम का जन्म हुआ। वे सत्य और धर्म पर चलते थे इसलिए ‘मर्यादा पुरुषोत्तम’ कहलाए।","en":"Shri Ram was born in Ayodhya. He walked the path of truth and dharma so he is called ‘Maryada Purushottam’."},"shot":{"who":["ram"],"setting":"Ayodhya palace","action":"baby Ram in Kaushalya's lap with Dasharath","expression":"joyful","camera":"medium warm shot"}},{"id":2,"text":{"gu":"પિતાના વચન માટે રામ વનમાં ગયા અને ત્યાં રાવણને હરાવી સીતાજીને પાછા લાવ્યા.","hi":"पिता के वचन के लिए राम वन गए और वहाँ रावण को हराकर सीता जी को वापस लाए।","en":"For his father's word Ram went to the forest and defeated Ravan and brought Sita back."},"shot":{"who":["ram","sita","laxman"],"setting":"a forest road","action":"Ram, Sita and Laxman walking in the forest calmly","expression":"calm","camera":"wide shot"}},{"id":3,"text":{"gu":"ચૌદ વર્ષ પછી અયોધ્યા પાછા ફર્યા અને રામરાજ્ય સ્થાપ્યું. એ યાદમાં આપણે દિવાળી ઊજવીએ છીએ.","hi":"चौदह वर्ष बाद अयोध्या लौटकर रामराज्य स्थापित किया। उसी की याद में हम दीवाली मनाते हैं।","en":"After fourteen years he returned to Ayodhya and established Ramrajya. In its memory we celebrate Diwali."},"shot":{"who":["ram","sita","laxman","hanuman"],"setting":"Ayodhya with diyas","action":"Ram on the throne with family and Hanuman","expression":"joyful","camera":"wide festive shot"}}],"lesson":{"gu":"શ્રીરામ શીખવે છે: સત્ય બોલો, વચન નિભાવો અને બધા સાથે પ્રેમથી વર્તો.","hi":"श्रीराम सिखाते हैं: सत्य बोलो, वचन निभाओ और सबसे प्रेम से व्यवहार करो।","en":"Shri Ram teaches us: speak truth, keep your word and treat all with love."}},{"id":"krishna","char":"krishna","order":8,"yuga":{"gu":"દ્વાપરયુગ","hi":"द्वापरयुग","en":"Dwapar Yuga"},"form":{"gu":"ગોવાળ, સારથિ","hi":"ग्वाला, सारथी","en":"Cowherd and charioteer"},"scenes":[{"id":1,"text":{"gu":"મથુરામાં જન્મ્યા અને ગોકુળમાં ઉછર્યા. માખણચોર કાન્હા બધાનો પ્રિય હતો.","hi":"मथुरा में जन्मे और गोकुल में पले। माखनचोर कान्हा सबका प्रिय था।","en":"Born in Mathura and raised in Gokul, the butter-loving Kanha was everyone's favourite."},"shot":{"who":["krishna"],"setting":"a Gokul village","action":"little Krishna with a pot of butter, laughing","expression":"naughty","camera":"medium cheerful shot"}},{"id":2,"text":{"gu":"કૃષ્ણે ગોવર્ધન પર્વત ઊંચકી ગામવાસીઓને વરસાદથી બચાવ્યા. વાંસળીથી બધાને મોહિત કર્યા.","hi":"कृष्ण ने गोवर्धन पर्वत उठाकर गाँववालों को वर्षा से बचाया। बाँसुरी से सबको मोहित किया।","en":"Krishna lifted Mount Govardhan to protect villagers from rain. He charmed everyone with his flute."},"shot":{"who":["krishna"],"setting":"a rainy hill","action":"Krishna holds the hill on his little finger as villagers shelter under it","expression":"calm","camera":"wide shot"}},{"id":3,"text":{"gu":"મહાભારતમાં કૃષ્ણ અર્જુનના સારથિ બન્યા અને તેને ગીતાનો ઉપદેશ આપ્યો — કર્મ કરો, ફળની ચિંતા ન કરો.","hi":"महाभारत में कृष्ण अर्जुन के सारथी बने और उसे गीता का उपदेश दिया — कर्म करो, फल की चिंता न करो।","en":"In the Mahabharata Krishna became Arjun's charioteer and taught him the Gita — do your duty without worrying about the fruit."},"shot":{"who":["krishna","arjun"],"setting":"a golden chariot at dawn","action":"Krishna holds reins and speaks calmly to Arjun","expression":"wise","camera":"medium shot"}}],"lesson":{"gu":"શ્રીકૃષ્ણ શીખવે છે: કર્મ કરો, ફળની ચિંતા ન કરો અને હંમેશાં ખુશ રહો.","hi":"श्रीकृष्ण सिखाते हैं: कर्म करो, फल की चिंता मत करो और सदा प्रसन्न रहो।","en":"Shri Krishna teaches us: do your duty, don't worry about results and stay cheerful."}},{"id":"buddha","char":"buddha","order":9,"yuga":{"gu":"કલિયુગની શરૂઆતમાં (માન્યતા મુજબ)","hi":"कलियुग के आरंभ में (मान्यता अनुसार)","en":"Early Kali Yuga (according to tradition)"},"form":{"gu":"શાંત સાધુ","hi":"शांत साधु","en":"A peaceful monk"},"scenes":[{"id":1,"text":{"gu":"પરંપરા મુજબ બુદ્ધને વિષ્ણુનો નવમો અવતાર માનવામાં આવે છે. તેઓ રાજકુમાર હતા પણ સંસારનાં દુઃખ જોઈ ચિંતિત થયા.","hi":"परंपरा के अनुसार बुद्ध को विष्णु का नौवाँ अवतार माना जाता है। वे राजकुमार थे पर संसार के दुःख देखकर चिंतित हुए।","en":"According to tradition Buddha is considered Vishnu's ninth avatar. He was a prince but grew thoughtful on seeing the world's sorrows."},"shot":{"who":["buddha"],"setting":"a palace garden at dawn","action":"young prince Buddha looks at a distant road thoughtfully","expression":"thoughtful","camera":"medium shot"}},{"id":2,"text":{"gu":"તેમણે ધ્યાન કરી જ્ઞાન મેળવ્યું અને લોકોને અહિંસા, કરુણા અને શાંતિનો માર્ગ બતાવ્યો.","hi":"उन्होंने ध्यान करके ज्ञान पाया और लोगों को अहिंसा, करुणा और शांति का मार्ग बताया।","en":"He gained enlightenment through meditation and showed people the way of non-violence, compassion and peace."},"shot":{"who":["buddha"],"setting":"a bodhi tree at dawn","action":"Buddha meditates peacefully under a bodhi tree","expression":"serene","camera":"wide shot"}},{"id":3,"text":{"gu":"બુદ્ધનો સંદેશ ભારતથી આખા એશિયામાં ફેલાયો. કરુણા અને શાંતિ આજે પણ બધા માટે જરૂરી છે.","hi":"बुद्ध का संदेश भारत से पूरे एशिया में फैला। करुणा और शांति आज भी सबके लिए आवश्यक हैं।","en":"Buddha's message spread from India across Asia. Compassion and peace are still needed by all."},"shot":{"who":["buddha"],"setting":"a hillside monastery","action":"monks and children sit with palms together in peace","expression":"peaceful","camera":"wide shot"}}],"lesson":{"gu":"બુદ્ધ શીખવે છે: કરુણા રાખો, હિંસા ન કરો અને શાંત રહો.","hi":"बुद्ध सिखाते हैं: करुणा रखो, हिंसा मत करो और शांत रहो।","en":"Buddha teaches us: be compassionate, avoid violence and stay calm."}},{"id":"kalki","char":"kalki","order":10,"yuga":{"gu":"કલિયુગના અંતે (ભવિષ્યમાં)","hi":"कलियुग के अंत में (भविष्य में)","en":"End of Kali Yuga (in the future)"},"form":{"gu":"સફેદ ઘોડા પર સવાર","hi":"श्वेत अश्व पर सवार","en":"Riding a white horse"},"scenes":[{"id":1,"text":{"gu":"પુરાણો કહે છે કે કલિયુગના અંતે જ્યારે અધર્મ બહુ વધશે ત્યારે ભગવાન વિષ્ણુ કલ્કિ રૂપે આવશે.","hi":"पुराण कहते हैं कि कलियुग के अंत में जब अधर्म बहुत बढ़ेगा तब भगवान विष्णु कल्कि रूप में आएँगे।","en":"The Puranas say that at the end of Kali Yuga, when adharma grows too much, Lord Vishnu will come as Kalki."},"shot":{"who":["kalki"],"setting":"a calm future sky at dawn","action":"a bright vision of Kalki on a white horse appears above hills","expression":"hopeful","camera":"wide shot"}},{"id":2,"text":{"gu":"તેઓ સફેદ ઘોડા પર સવાર થશે અને હાથમાં તેજસ્વી તલવાર હશે. તેઓ અસત્યનો નાશ કરી સત્યને સ્થાપિત કરશે.","hi":"वे श्वेत अश्व पर सवार होंगे और हाथ में तेजस्वी तलवार होगी। वे असत्य का नाश कर सत्य की स्थापना करेंगे।","en":"He will ride a white horse with a shining sword in hand. He will end untruth and establish truth."},"shot":{"who":["kalki"],"setting":"a golden dawn","action":"Kalki rides a white horse across a bright field","expression":"calm strength","camera":"wide shot"}},{"id":3,"text":{"gu":"ત્યારે ફરી સત્યયુગ શરૂ થશે. આ કથા આપણને આશા આપે છે કે અંતે સત્યની જીત થાય છે.","hi":"तब फिर सत्ययुग आरंभ होगा। यह कथा हमें आशा देती है कि अंत में सत्य की जीत होती है।","en":"Then Satya Yuga will begin again. This story gives hope that truth wins in the end."},"shot":{"who":["kalki"],"setting":"a blooming landscape","action":"a peaceful world with children playing and flowers everywhere","expression":"joyful","camera":"wide shot"}}],"lesson":{"gu":"કલ્કિ અવતાર શીખવે છે: સત્યમાં વિશ્વાસ રાખો, આશા ન છોડો.","hi":"कल्कि अवतार सिखाता है: सत्य में विश्वास रखो, आशा मत छोड़ो।","en":"Kalki teaches us: have faith in truth and never lose hope."}}]}};
